import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, Modality } from "@google/genai";
import { useAppContext } from '../contexts/AppContext';
import { decode, decodeAudioData } from '../utils/media';

const SentinelIcon = () => (
    <svg className="w-8 h-8" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M12 2L3 7V12C3 18.2 7.1 23 12 24C16.9 23 21 18.2 21 12V7L12 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        <path d="M12 8V16" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        <path d="M8 12H16" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        <circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="1" className="animate-pulse" />
    </svg>
);

const CyberGrid = () => (
    <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-20">
        <div className="absolute inset-0" style={{ backgroundImage: 'linear-gradient(var(--accent-primary) 1px, transparent 1px), linear-gradient(90deg, var(--accent-primary) 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>
    </div>
);

const GuideBot: React.FC = () => {
    const { lang, theme } = useAppContext();
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState<{ role: 'bot' | 'user'; text: string }[]>([]);
    const [input, setInput] = useState('');
    const [isThinking, setIsThinking] = useState(false);
    const [isTalking, setIsTalking] = useState(false);
    const chatRef = useRef<HTMLDivElement>(null);
    const audioContextRef = useRef<AudioContext | null>(null);

    // Initial greeting
    useEffect(() => {
        const greetings: Record<string, string> = {
            en: "Sentinel Protocol Active. Identity verified. I am your Vanhsya Cyber-Guide. How can I secure your next adventure?",
            es: "Protocolo Sentinel Activo. Identidad verificada. Soy tu Ciber-Guía de Vanhsya. ¿Cómo puedo asegurar tu próxima aventura?",
            hi: "सेंटिनल प्रोटोकॉल सक्रिय। पहचान सत्यापित। मैं आपका वनह्स्या साइबर-गाइड हूं। मैं आपकी अगली साहसिक यात्रा को कैसे सुरक्षित कर सकता हूं?",
            ar: "بروتوكول السنتينل نشط. تم التحقق من الهوية. أنا دليلك السيبراني في فانهسيا. كيف يمكنني تأمين مغامرتك القادمة؟"
        };
        setMessages([{ role: 'bot', text: greetings[lang] || greetings.en }]);
    }, [lang]);

    useEffect(() => {
        if (chatRef.current) {
            chatRef.current.scrollTop = chatRef.current.scrollHeight;
        }
    }, [messages]);

    const playSpeech = async (text: string) => {
        try {
            setIsTalking(true);
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: [{ parts: [{ text: `Respond in ${lang}: ${text}` }] }],
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: {
                        voiceConfig: {
                            prebuiltVoiceConfig: { voiceName: lang === 'hi' ? 'Kore' : 'Puck' }, // Vary voices based on language
                        },
                    },
                },
            });

            const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
            if (base64Audio) {
                if (!audioContextRef.current) {
                    audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                }
                const ctx = audioContextRef.current;
                const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(ctx.destination);
                source.onended = () => setIsTalking(false);
                source.start();
            } else {
                setIsTalking(false);
            }
        } catch (err) {
            console.error("Speech synthesis failed", err);
            setIsTalking(false);
        }
    };

    const handleSend = async () => {
        if (!input.trim() || isThinking) return;

        const userMsg = input;
        setInput('');
        setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
        setIsThinking(true);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const systemPrompt = `
                You are the 'VANHSYA SENTINEL', a world-class cybersecurity AI and tour guide for the Vanhsya Global Travel platform.

                CORE RULES:
                1. RESPOND ONLY IN THE USER'S LANGUAGE: ${lang.toUpperCase()}.
                2. PERSONA: You are systematic, highly secure, and futuristic. Use terms like 'Intel', 'Clearance', 'Protocol', and 'Encrypted'.
                3. SCOPE: You only answer questions about Vanhsya adventures, the AI Planner, VR Experiences, Pricing Protocols (111, 222, 333), YNO Tokens, and website features. 
                4. REJECTION: If asked about anything else (e.g., weather in Paris - unless it's a Vanhsya tour, politics, general facts), politely decline stating it's 'outside your security clearance'.
                5. CONCISE: Keep briefings short and high-impact.
            `;

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: userMsg,
                config: {
                    systemInstruction: systemPrompt,
                }
            });

            const botText = response.text || "Encryption error. Protocol failed to return data.";
            setMessages(prev => [...prev, { role: 'bot', text: botText }]);
            setIsThinking(false);

            // Speak the response
            await playSpeech(botText);

        } catch (err) {
            console.error("Bot logic failed", err);
            setMessages(prev => [...prev, { role: 'bot', text: "Critical System Error. Sentinel offline." }]);
            setIsThinking(false);
        }
    };

    return (
        <div className="fixed bottom-6 right-6 z-[100] font-sans">
            {/* The Orb / Button */}
            {!isOpen && (
                <button 
                    onClick={() => setIsOpen(true)}
                    className="group relative h-16 w-16 rounded-full bg-black border-2 border-[var(--accent-primary)] flex items-center justify-center text-[var(--accent-primary)] shadow-[0_0_20px_var(--shadow-color-primary)] hover:scale-110 transition-all duration-500"
                >
                    <div className="absolute inset-0 rounded-full border border-[var(--accent-primary)] animate-ping opacity-20"></div>
                    <SentinelIcon />
                </button>
            )}

            {/* The Terminal */}
            {isOpen && (
                <div className="w-[350px] sm:w-[400px] h-[550px] bg-black/90 backdrop-blur-2xl border-2 border-[var(--accent-primary)] rounded-3xl shadow-[0_0_50px_rgba(0,242,254,0.3)] flex flex-col overflow-hidden animate-fadeIn relative">
                    <CyberGrid />

                    {/* Header */}
                    <div className="p-4 border-b border-[var(--accent-primary)]/30 flex items-center justify-between bg-[var(--accent-primary)]/5 relative z-10">
                        <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-lg bg-[var(--accent-primary)]/10 text-[var(--accent-primary)] ${isTalking ? 'animate-pulse' : ''}`}>
                                <SentinelIcon />
                            </div>
                            <div>
                                <h3 className="font-black text-sm tracking-[0.2em] text-white">VANHSYA SENTINEL</h3>
                                <p className="text-[10px] text-[var(--accent-primary)] font-mono animate-pulse">● PROTOCOL v4.2 LIVE</p>
                            </div>
                        </div>
                        <button onClick={() => setIsOpen(false)} className="text-gray-500 hover:text-white transition-colors">
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                    </div>

                    {/* Messages */}
                    <div ref={chatRef} className="flex-grow overflow-y-auto p-4 space-y-4 relative z-10 scroll-smooth">
                        {messages.map((m, i) => (
                            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                <div className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed ${
                                    m.role === 'user' 
                                    ? 'bg-[var(--accent-secondary)]/20 border border-[var(--accent-secondary)]/30 text-white rounded-br-none' 
                                    : 'bg-white/5 border border-white/10 text-gray-300 rounded-bl-none font-mono'
                                }`}>
                                    {m.text}
                                </div>
                            </div>
                        ))}
                        {isThinking && (
                            <div className="flex justify-start">
                                <div className="bg-white/5 border border-white/10 p-3 rounded-2xl rounded-bl-none flex gap-1">
                                    <div className="w-1.5 h-1.5 bg-[var(--accent-primary)] rounded-full animate-bounce"></div>
                                    <div className="w-1.5 h-1.5 bg-[var(--accent-primary)] rounded-full animate-bounce [animation-delay:0.2s]"></div>
                                    <div className="w-1.5 h-1.5 bg-[var(--accent-primary)] rounded-full animate-bounce [animation-delay:0.4s]"></div>
                                </div>
                            </div>
                        )}
                        {isTalking && (
                            <div className="flex justify-center py-2">
                                <div className="flex items-center gap-1.5">
                                    {[1,2,3,4,5].map(i => (
                                        <div key={i} className="w-1 h-4 bg-[var(--accent-primary)] animate-pulse" style={{ animationDelay: `${i * 0.1}s` }}></div>
                                    ))}
                                    <span className="text-[10px] font-mono text-[var(--accent-primary)] ml-2 uppercase tracking-widest">Broadcasting Intel...</span>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Footer */}
                    <div className="p-4 border-t border-[var(--accent-primary)]/30 bg-black/50 relative z-10">
                        <div className="flex gap-2">
                            <input 
                                type="text"
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                                placeholder="Request intel..."
                                className="flex-grow bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-sm text-white focus:outline-none focus:border-[var(--accent-primary)] transition-all font-mono"
                            />
                            <button 
                                onClick={handleSend}
                                disabled={isThinking}
                                className="bg-[var(--accent-primary)] text-black p-2.5 rounded-xl hover:brightness-110 transition-all disabled:opacity-50"
                            >
                                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                            </button>
                        </div>
                        <div className="mt-3 flex justify-between items-center text-[8px] font-mono text-gray-600 uppercase tracking-widest">
                            <span>Secured by Vanhsya Cryptography</span>
                            <span>Clearance: Level 5</span>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

