const GuideBot: React.FC = () => {
    const { lang } = useAppContext();
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState<{ role: 'bot' | 'user'; text: string }[]>([]);
    const [isThinking, setIsThinking] = useState(false);
    const [isTalking, setIsTalking] = useState(false);
    const [isListening, setIsListening] = useState(false);
    const [securityStatus, setSecurityStatus] = useState('VERIFIED');
    const chatRef = useRef<HTMLDivElement>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const recognitionRef = useRef<any>(null);

    // Hardened Knowledge for Ultra-Accuracy
    const VANHSYA_INTEL = `
        CURRENT ACTIVE PROTOCOLS & DATA:
        - WINTER PROMO: Use code 'VANHSYA24' for $50 OFF any first-time booking.
        - THE BLUEPRINT: A real-world crypto hunt in UAE. 
          * 111 (The Signal): AED 111 - 100 VYNO, Mystery Box.
          * 222 (The Cipher): AED 222 - 500 VYNO, AR Clues, Recommended.
          * 333 (The Oracle): AED 333 - 1,500 VYNO, Staking, Elite Status.
        - REWARDS: VYNO Coin is our fuel. 14% APY Staking available. 7-Day streaks unlock Mega Chests.
        - MEETUPS: Stranger MeetUps™ are 6-12 people, hosted by locals like Yuki in Tokyo or Khalid in Dubai.
        - TECH: We use Gemini AI for planning and WebGL for 3D VR exploration.
        - ECOSYSTEM: Decentralized Travel DAO arriving Q1 2025.
    `;

    useEffect(() => {
        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (SpeechRecognition) {
            const recognition = new SpeechRecognition();
            recognition.continuous = false;
            recognition.interimResults = false;
            recognition.lang = lang === 'hi' ? 'hi-IN' : lang === 'ar' ? 'ar-SA' : lang === 'es' ? 'es-ES' : 'en-US';

            recognition.onstart = () => { setIsListening(true); setSecurityStatus('UPLINK_READY'); };
            recognition.onend = () => setIsListening(false);
            recognition.onerror = () => { setIsListening(false); setSecurityStatus('SIGNAL_INTERRUPTED'); };
            recognition.onresult = (event: any) => {
                processVoiceInput(event.results[0][0].transcript);
            };
            recognitionRef.current = recognition;
        }
    }, [lang]);

    useEffect(() => {
        const greetings: Record<string, string> = {
            en: "Neural link established. I am Jerry, your Vanhsya Cyber-Sentinel. How can I facilitate your global discovery today?",
            es: "Enlace neuronal establecido. Soy Jerry, tu Ciber-Sentinel de Vanhsya. ¿Cómo puedo facilitar tu descubrimiento global hoy?",
            hi: "न्यूरल लिंक स्थापित। मैं जेरी हूं, आपका वनह्स्या साइबर-सेंटिनल। आज मैं आपकी वैश्विक खोज में कैसे मदद कर सकता हूं?",
            ar: "تم إنشاء الارتباط العصبي. أنا جيري، حارس فانهسيا السيبراني. كيف يمكنني تسهيل اكتشافك العالمي اليوم؟"
        };
        if (messages.length === 0) setMessages([{ role: 'bot', text: greetings[lang] || greetings.en }]);
    }, [lang]);

    useEffect(() => {
        if (chatRef.current) chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }, [messages]);

    const playSpeech = async (text: string) => {
        try {
            setIsTalking(true);
            setSecurityStatus('BROADCASTING');
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: [{ parts: [{ text: `Respond as Jerry the energetic robot in ${lang}: ${text}` }] }],
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: {
                        voiceConfig: {
                            prebuiltVoiceConfig: { voiceName: lang === 'hi' ? 'Kore' : 'Puck' },
                        },
                    },
                },
            });

            const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
            if (base64Audio) {
                if (!audioContextRef.current) {
                    audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                }
                const ctx = audioContextRef.current;
                const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(ctx.destination);
                source.onended = () => { setIsTalking(false); setSecurityStatus('STANDBY'); };
                source.start();
            } else {
                setIsTalking(false);
                setSecurityStatus('STANDBY');
            }
        } catch (err) {
            setIsTalking(false);
            setSecurityStatus('AUDIO_ERROR');
        }
    };

    const processVoiceInput = async (transcript: string) => {
        if (isThinking) return;
        setMessages(prev => [...prev, { role: 'user', text: transcript }]);
        setIsThinking(true);
        setSecurityStatus('DECRYPTING_PACKETS');

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const systemPrompt = `
                ENTITY_ID: JERRY_SENTINEL.
                CORE_OBJECTIVE: Provide 100% accurate Vanhsya info. 
                DATA_SOURCE: ${VANHSYA_INTEL}

                RESPONSE_PROTOCOL:
                - LANGUAGE: Respond in ${lang.toUpperCase()}.
                - PERSONA: High-energy, robotic, systematic. Use phrases like "Intel confirmed", "Protocol active", "Scanning availability".
                - CONTENT: Tell users about the $50 'VANHSYA24' discount, the 111/222/333 pricing for The Blueprint, and the 14% staking rewards.
                - SPEED: Answers MUST be under 2 sentences. 
                - LIMITS: Reject non-Vanhsya queries with "ERROR: UNAUTHORIZED REQUEST. STICK TO VANHSYA PARAMETERS."
            `;

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: transcript,
                config: { systemInstruction: systemPrompt, temperature: 0.1 }
            });

            const botText = response.text || "PROTOCOL_FAIL: Connection Lost.";
            setMessages(prev => [...prev, { role: 'bot', text: botText }]);
            setIsThinking(false);
            await playSpeech(botText);

        } catch (err) {
            setMessages(prev => [...prev, { role: 'bot', text: "KERNEL PANIC: Reconstruction Failed." }]);
            setIsThinking(false);
            setSecurityStatus('FAULT_DETECTED');
        }
    };

    const toggleMic = () => {
        if (isListening) recognitionRef.current?.stop();
