                    <SentinelIcon />
                    <span className="absolute -top-14 right-0 bg-[var(--accent-primary)] text-black text-[10px] font-black px-3 py-1.5 rounded-lg opacity-0 group-hover:opacity-100 transition-all transform group-hover:-translate-y-2 whitespace-nowrap shadow-xl">ACTIVATE SENTINEL</span>
                </button>
            ) : (
