                    {/* Futuristic Header */}
                    <div className="p-7 border-b border-white/10 flex items-center justify-between bg-black/50 relative">
                        <div className="absolute top-0 left-0 w-full h-[1px] bg-gradient-to-r from-transparent via-[var(--accent-primary)] to-transparent opacity-50"></div>
                        <div className="flex items-center gap-4">
                            <div className={`p-3 rounded-2xl bg-black border border-[var(--accent-primary)]/30 text-[var(--accent-primary)] ${isTalking ? 'shadow-[0_0_25px_var(--accent-primary)]' : ''}`}>
                                <SentinelIcon />
                            </div>
                            <div>
                                <h3 className="font-black text-[10px] tracking-[0.4em] text-white uppercase">Neural_Uplink_Live</h3>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className={`w-2 h-2 rounded-full ${securityStatus.includes('ERROR') ? 'bg-red-500' : 'bg-green-500'} animate-pulse shadow-[0_0_10px_currentColor]`}></span>
                                    <span className="text-[9px] text-[var(--accent-primary)] font-black tracking-widest uppercase">System: {securityStatus}</span>
                                </div>
                            </div>
                        </div>
                        <button onClick={() => setIsOpen(false)} className="text-gray-500 hover:text-white transition-all hover:rotate-90">
                            <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
