                    {/* Data Log */}
                    <div ref={chatRef} className="flex-grow overflow-y-auto p-7 space-y-6 max-h-[280px] custom-scrollbar bg-black/20">
                        {messages.map((m, i) => (
                            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
