                            </div>
                        ))}
                        {isThinking && (
                            <div className="flex items-center gap-3 text-[9px] text-[var(--accent-primary)] animate-pulse tracking-[0.5em] font-black pl-2">
                                [ DECRYPTING_PACKETS... ]
                            </div>
                        )}
                    </div>

                    {/* Neural Interface Hub */}
                    <div className="p-10 border-t border-white/5 bg-black/60 flex flex-col items-center gap-10 relative">

                        <div className="flex flex-col items-center gap-2">
                            <NeuralCore isActive={isTalking || isListening} />
