                </button>
            ) : (
                <div className="w-[360px] sm:w-[450px] bg-black/90 backdrop-blur-3xl border-2 border-[var(--accent-primary)] rounded-[3rem] shadow-[0_0_100px_rgba(0,242,254,0.4)] flex flex-col overflow-hidden animate-fadeIn border-t-[var(--accent-primary)]">

