    const audioContextRef = useRef<AudioContext | null>(null);
    const currentAudioSource = useRef<AudioBufferSourceNode | null>(null);
    const recognitionRef = useRef<any>(null);

    const VANHSYA_INTEL = `
        JERRY PROTOCOL V6.0 (Enhanced Intelligence):
        - CORE IDENTITY: Systematic, fast, accurate, highly responsive robotic sentinel.
        - CURRENT OFFERS: Use code 'VANHSYA24' for a $50/AED 185 reduction on any booking.
        - TREASURE HUNT (THE BLUEPRINT): 
          * Protocol 111: Entry level, AED 111 (100 VYNO, Mystery Box).
          * Protocol 222: Advanced level, AED 222 (500 VYNO, AR Clues). Recommended.
          * Protocol 333: Legendary level, AED 333 (1500 VYNO, Staking, Physical Keys).
        - REWARDS: VYNO Coin is native fuel. Staking yields 14% APY.
        - MISSION: Guide explorers with Level 10 Security precision.
    `;

    useEffect(() => {
        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (SpeechRecognition) {
            const recognition = new SpeechRecognition();
            recognition.continuous = false;
            recognition.interimResults = false;
            recognition.lang = lang === 'hi' ? 'hi-IN' : lang === 'ar' ? 'ar-SA' : lang === 'es' ? 'es-ES' : 'en-US';

            recognition.onstart = () => { setIsListening(true); setSystemStatus('LISTENING'); };
            recognition.onend = () => setIsListening(false);
            recognition.onresult = (event: any) => {
                processVoiceInput(event.results[0][0].transcript);
            };
            recognitionRef.current = recognition;
        }
    }, [lang]);

    useEffect(() => {
        const greetings: Record<string, string> = {
            en: "Uplink verified. Sentinel Jerry initialized. How can I facilitate your global discovery protocol today?",
            es: "Enlace verificado. Sentinel Jerry inicializado. ¿Cómo puedo facilitar su protocolo de descubrimiento hoy?",
            hi: "अपलिंक सत्यापित। सेंटिनल जेरी शुरू किया गया। आज मैं आपकी वैश्विक खोज में कैसे मदद कर सकता हूं?",
            ar: "تم التحقق من الارتباط. جيري السنتينل جاهز. كيف يمكنني تسهيل بروتوكول الاكتشاف الخاص بك اليوم؟"
        };
        if (messages.length === 0) setMessages([{ role: 'bot', text: greetings[lang] || greetings.en }]);
    }, [lang]);

    useEffect(() => {
        if (chatRef.current) chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }, [messages]);

    const stopAudio = () => {
        if (currentAudioSource.current) {
            try {
                currentAudioSource.current.stop();
            } catch (e) { /* ignore already stopped */ }
            currentAudioSource.current = null;
        }
        setIsTalking(false);
    };

    const playSpeech = async (text: string) => {
        stopAudio();
        try {
            setIsTalking(true);
            setSystemStatus('BROADCASTING');
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: [{ parts: [{ text: `Act as Jerry the robotic guide. Respond with technical precision in ${lang}: ${text}` }] }],
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: {
                        voiceConfig: {
                            prebuiltVoiceConfig: { voiceName: lang === 'hi' ? 'Kore' : 'Puck' },
                        },
                    },
                },
            });

            const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
            if (base64Audio) {
                if (!audioContextRef.current) {
                    audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                }
                const ctx = audioContextRef.current;
                const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(ctx.destination);
                source.onended = () => { 
                    setIsTalking(false); 
                    setSystemStatus('SECURE');
                    if (clearance < 10) setClearance(prev => prev + 1);
                };
                currentAudioSource.current = source;
                source.start();
            } else {
                setIsTalking(false);
                setSystemStatus('SECURE');
            }
        } catch (err) {
            setIsTalking(false);
            setSystemStatus('ERROR');
        }
    };

    const processVoiceInput = async (transcript: string) => {
        if (isThinking) return;
        setMessages(prev => [...prev, { role: 'user', text: transcript }]);
        setIsThinking(true);
        setSystemStatus('DECRYPTING');

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const systemPrompt = `
                IDENT: JERRY_SENTINEL_V6.
                DATA_SOURCE: ${VANHSYA_INTEL}

                PROTOCOLS:
                - BEHAVIOR: High-precision, robotic, energetic, World-Class guide.
                - SPEED: Max 2 concise sentences. Be ultra-fast.
                - INTERFERENCE: If user interrupts, handle with "INTERFERENCE DETECTED. ADJUSTING PACKETS."
                - CONTENT: Only talk about Vanhsya trips, UAE missions (111/222/333), rewards, and ecosystem. 
                - SECURITY: Reject non-Vanhsya data requests with "ERROR: UNAUTHORIZED REQUEST. DATA ENCRYPTED."
                - LANGUAGE: Respond strictly in ${lang.toUpperCase()}.
            `;

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: transcript,
                config: { systemInstruction: systemPrompt, temperature: 0.1 }
            });

            const botText = response.text || "SYSTEM_FAIL: Response Corrupted.";
            setMessages(prev => [...prev, { role: 'bot', text: botText }]);
            setIsThinking(false);
            await playSpeech(botText);

        } catch (err) {
            setMessages(prev => [...prev, { role: 'bot', text: "KERNEL_PANIC: Reconstruction Failed." }]);
            setIsThinking(false);
            setSystemStatus('HALTED');
        }
    };

    const toggleMic = () => {
        if (isTalking) stopAudio();
        if (isListening) recognitionRef.current?.stop();
        else recognitionRef.current?.start();
    };

    return (
        <div className="fixed bottom-6 right-6 z-[100] font-mono">
            <style>{`
                @keyframes jerry-pulse { from { height: 10%; } to { height: 100%; } }
                @keyframes scanline { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: var(--accent-primary); border-radius: 10px; }
            `}</style>

            {!isOpen ? (
                <button 
                    onClick={() => setIsOpen(true)}
                    className="h-24 w-24 rounded-3xl bg-black border-2 border-[var(--accent-primary)] flex items-center justify-center text-[var(--accent-primary)] shadow-[0_0_50px_var(--shadow-color-primary)] hover:scale-110 transition-all duration-500 group relative rotate-3 hover:rotate-0"
                >
                    <div className="absolute inset-0 rounded-3xl border border-[var(--accent-primary)] animate-ping opacity-20"></div>
                    <SentinelIcon />
                    <span className="absolute -top-14 right-0 bg-black border border-[var(--accent-primary)] text-[var(--accent-primary)] text-[9px] font-black px-3 py-1.5 rounded-lg opacity-0 group-hover:opacity-100 transition-all transform group-hover:-translate-y-2 whitespace-nowrap shadow-xl">WAKE SENTINEL</span>
                </button>
            ) : (
                <div className="w-[380px] sm:w-[460px] bg-black/95 backdrop-blur-3xl border-2 border-[var(--accent-primary)] rounded-[3rem] shadow-[0_0_120px_rgba(0,242,254,0.5)] flex flex-col overflow-hidden animate-fadeIn border-t-[var(--accent-primary)]">

                    {/* Security Overlay */}
                    <div className="absolute inset-0 pointer-events-none opacity-30 z-0">
                        <div className="absolute top-0 left-0 w-full h-[2px] bg-gradient-to-r from-transparent via-[var(--accent-primary)] to-transparent animate-[scanline_3s_linear_infinite]"></div>
                        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,var(--accent-primary)_0.5px,transparent_1px)] bg-[length:12px_12px]"></div>
                    </div>

                    {/* HUD Header */}
                    <div className="p-8 border-b border-[var(--accent-primary)]/20 flex items-center justify-between bg-black/80 relative z-10">
                        <div className="flex items-center gap-5">
                            <div className={`p-3 rounded-2xl bg-black border-2 border-[var(--accent-primary)]/40 text-[var(--accent-primary)] ${isTalking ? 'shadow-[0_0_30px_var(--accent-primary)] scale-110' : ''} transition-all duration-300`}>
                                <SentinelIcon />
                            </div>
                            <div>
                                <h3 className="font-black text-sm tracking-[0.4em] text-white">SENTINEL_JERRY</h3>
                                <div className="flex items-center gap-2 mt-1.5">
                                    <span className={`w-2 h-2 rounded-full ${systemStatus.includes('ERROR') ? 'bg-red-500' : 'bg-green-500'} animate-pulse shadow-[0_0_10px_currentColor]`}></span>
                                    <span className="text-[10px] text-[var(--accent-primary)] uppercase font-black tracking-widest">UPLINK: {systemStatus}</span>
                                </div>
                            </div>
                        </div>
                        <button onClick={() => setIsOpen(false)} className="text-gray-500 hover:text-white transition-all p-3 hover:bg-white/5 rounded-full hover:rotate-90">
                            <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                    </div>

                    {/* Security Ticker */}
                    <div className="bg-[var(--accent-primary)]/10 py-2 px-8 text-[9px] font-black text-[var(--accent-primary)] uppercase tracking-[0.3em] flex justify-between border-b border-[var(--accent-primary)]/20 relative z-10 backdrop-blur-md">
                        <span className="flex items-center gap-2"><span className="animate-pulse">●</span> CLEARANCE_LVL_{clearance}</span>
                        <span className="flex items-center gap-2">ENCRYPTION: AES-256</span>
                        <span className="animate-pulse">STABLE</span>
                    </div>

                    {/* Data Stream */}
                    <div ref={chatRef} className="flex-grow overflow-y-auto p-8 space-y-8 max-h-[260px] scroll-smooth relative z-10 custom-scrollbar bg-gradient-to-b from-black/0 via-black/20 to-black/60">
                        {messages.map((m, i) => (
                            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                                <div className={`max-w-[85%] p-5 rounded-[2rem] text-[12px] leading-relaxed border backdrop-blur-xl ${
                                    m.role === 'user' 
                                    ? 'bg-[var(--accent-secondary)]/15 border-[var(--accent-secondary)]/40 text-white rounded-br-none shadow-[0_15px_40px_rgba(var(--accent-secondary-rgb),0.1)]' 
                                    : 'bg-white/5 border-white/10 text-gray-200 rounded-bl-none shadow-[0_20px_50px_rgba(0,0,0,0.4)]'
                                }`}>
                                    <div className="flex justify-between items-center mb-3">
                                        <span className="opacity-40 text-[8px] font-black tracking-[0.3em] uppercase">
                                            {m.role === 'user' ? 'REMOTE_NODE' : 'SENTINEL_CORE'}
                                        </span>
                                        <span className="opacity-20 text-[7px] font-mono">0x{Math.floor(Math.random()*10000)}</span>
                                    </div>
                                    {m.text}
                                </div>
                            </div>
                        ))}
                        {isThinking && (
                            <div className="flex items-center gap-4 text-[10px] text-[var(--accent-primary)] animate-pulse tracking-[0.6em] font-black pl-4">
                                <div className="w-2 h-2 bg-current rounded-full"></div>
                                DECRYPTING_PACKETS_...
                            </div>
                        )}
                    </div>

                    {/* Interaction Hub */}
                    <div className="p-12 border-t border-[var(--accent-primary)]/20 bg-black/90 flex flex-col items-center gap-12 relative z-10 shadow-[0_-20px_50px_rgba(0,0,0,0.5)]">

                        <div className="flex flex-col items-center gap-6 w-full">
                            <NeuralCore isActive={isTalking || isListening} />
                            <AudioBars isActive={isTalking} />
                        </div>

                        <div className="relative group/mic">
                            {(isListening || isTalking) && (
                                <div className={`absolute -inset-8 rounded-full border-2 ${isListening ? 'border-red-500' : 'border-[var(--accent-primary)]'} animate-[ping_2s_linear_infinite] opacity-30`}></div>
                            )}
                            <button 
                                onClick={toggleMic}
                                disabled={isThinking}
                                className={`h-32 w-32 rounded-full border-4 flex flex-col items-center justify-center transition-all duration-500 shadow-2xl relative z-10 ${
                                    isListening 
                                    ? 'bg-red-950/40 border-red-500 text-red-500 scale-115 rotate-6' 
                                    : 'bg-black border-[var(--accent-primary)] text-[var(--accent-primary)] hover:border-white hover:text-white hover:shadow-[0_0_80px_var(--shadow-color-primary)]'
                                } disabled:opacity-20`}
                            >
                                <svg className={`w-14 h-14 mb-3 transition-transform duration-700 ${isListening ? 'scale-125' : ''}`} fill="currentColor" viewBox="0 0 24 24">
                                    <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/>
                                    <path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
                                </svg>
                                <span className="text-[11px] font-black uppercase tracking-[0.2em] text-center px-4">
                                    {isListening ? 'RECEIVING' : 'ACTIVATE_VOICE'}
                                </span>
                            </button>
                        </div>

                        <div className="w-full space-y-5">
                            <div className="flex justify-between items-center text-[9px] text-gray-500 font-black uppercase tracking-[0.6em]">
                                <span>SECURE_LINK: {isListening || isTalking ? 'ACTIVE' : 'IDLE'}</span>
                                <span>SIGNAL_STRENGTH: 99.9%</span>
                            </div>
                            <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden border border-white/10">
                                <div 
                                    className={`h-full bg-gradient-to-r from-[var(--accent-primary)] via-white to-[var(--accent-primary)] transition-all duration-1000 ease-out ${isTalking ? 'w-full shadow-[0_0_20px_#fff]' : 'w-0'}`}
                                ></div>
                            </div>
                        </div>
                    </div>

                    {/* Industrial Footer Ticker */}
                    <div className="bg-[var(--accent-primary)] py-2 px-8 text-black text-[9px] font-black uppercase tracking-[0.25em] flex justify-between items-center opacity-95 overflow-hidden relative z-10">
                        <span className="flex items-center gap-3 animate-pulse">
                            <span className="w-1.5 h-1.5 bg-black rounded-full"></span>
                            CORE_UPLINK_STABLE
                        </span>
                        <div className="flex items-center gap-10 whitespace-nowrap">
                            <span>LATENCY: 11ms</span>
                            <span>PROTOCOL: ENGAGED</span>
                            <span>VANHSYA_V6.0</span>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

