                        <span className="flex items-center gap-2">
                           <span className={`w-2 h-2 rounded-full ${status === 'LIVE' ? 'bg-green-600 animate-pulse' : 'bg-red-900'}`}></span>
                           {status}
                        </span>
                        <div className="flex items-center gap-10 whitespace-nowrap">
                            <span>ENCRYPTION: AES_256</span>
                            <span>NODE_0x{Math.floor(Math.random()*9999)}</span>
                        </div>
                    </div>

                    {/* HUD Header */}
                    <div className="p-8 border-b border-white/5 flex items-center justify-between bg-black/60 relative z-10">
                        <div className="flex items-center gap-5">
                            <div className={`p-3 rounded-2xl bg-black border-2 border-white/10 text-[var(--accent-primary)] transition-all duration-300 ${isTalking ? 'shadow-[0_0_30px_var(--accent-primary)]' : ''}`}>
                                <SentinelIcon />
                            </div>
                            <div>
                                <h3 className="font-black text-sm tracking-[0.4em] text-white uppercase">Neural_Uplink</h3>
                                <p className="text-[10px] text-gray-500 font-bold mt-1 tracking-widest">CLEARANCE: LVL_MAX</p>
                            </div>
                        </div>
                        <button onClick={() => { closeSession(); setIsOpen(false); }} className="text-gray-500 hover:text-white transition-all p-3 hover:bg-white/5 rounded-full hover:rotate-90">
                            <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                    </div>

                    {/* Interface Content */}
                    <div className="p-10 flex flex-col items-center gap-12 relative z-10">

                        <div className="flex flex-col items-center gap-4">
                            <NeuralOrb isActive={status === 'LIVE'} isThinking={status === 'CONNECTING'} />
                            <div className="h-6 text-center">
                                {transcription && (
                                    <p className="text-xs text-[var(--accent-primary)] font-bold italic animate-fadeIn">
                                        "{transcription}"
