                                )}
                            </div>
                        </div>

                        <div className="relative group/uplink">
                            {status === 'LIVE' && (
                                <div className="absolute -inset-10 rounded-full border-2 border-cyan-500/30 animate-[ping_3s_linear_infinite]"></div>
                            )}
                            <button 
                                onClick={connectToSentinel}
                                className={`h-36 w-36 rounded-full border-4 flex flex-col items-center justify-center transition-all duration-500 shadow-2xl relative z-10 ${
                                    status === 'LIVE' 
