                            >
                                <svg className={`w-14 h-14 mb-3 transition-transform duration-700 ${status === 'LIVE' ? 'scale-125' : ''}`} fill="currentColor" viewBox="0 0 24 24">
                                    {status === 'LIVE' ? (
