                                    )}
                                </svg>
                                <span className="text-[11px] font-black uppercase tracking-[0.2em] text-center px-4">
                                    {status === 'LIVE' ? 'ACTIVE_LINK' : status === 'CONNECTING' ? 'SYNCING...' : 'ESTABLISH_VOICE'}
                                </span>
                            </button>
