const ThreeCanvas: React.FC<ThreeCanvasProps> = ({ journey, globeSpeed }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const globeSpeedRef = useRef(globeSpeed);
  const globeGroupRef = useRef<any>(null);
  const atomsRef = useRef<any[]>([]);
  const plasmaLayerRef = useRef<any>(null);

  useEffect(() => {
    globeSpeedRef.current = globeSpeed;
  }, [globeSpeed]);

  useEffect(() => {
    const THREE = window.THREE;
    if (!mountRef.current || !THREE) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 10;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const clock = new THREE.Clock();

    // --- LIGHTING (Solar Spectrum) ---
    const ambientLight = new THREE.AmbientLight(0xffcc00, 0.3);
    scene.add(ambientLight);
    const sunLight = new THREE.PointLight(0xffaa00, 3, 100);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);

    const globeGroup = new THREE.Group();
    globeGroupRef.current = globeGroup;
    const RADIUS = 4.5;

    // --- SOLAR CORE (The "Sun" Globe) ---
    const sunGeo = new THREE.SphereGeometry(RADIUS, 64, 64);
    const sunMat = new THREE.MeshStandardMaterial({
        color: 0xff4400,
        emissive: 0xffaa00,
        emissiveIntensity: 1.5,
        roughness: 0,
        metalness: 1,
        transparent: true,
        opacity: 0.9,
    });
    const sunCore = new THREE.Mesh(sunGeo, sunMat);
    globeGroup.add(sunCore);

    // --- PLASMA/MERCURY FLUID LAYER ---
    const plasmaGeo = new THREE.SphereGeometry(RADIUS * 1.05, 64, 64);
    const plasmaMat = new THREE.MeshPhongMaterial({
        color: 0xffff00,
        specular: 0xffffff,
        shininess: 100,
        transparent: true,
        opacity: 0.3,
        blending: THREE.AdditiveBlending
    });
    const plasma = new THREE.Mesh(plasmaGeo, plasmaMat);
    plasmaLayerRef.current = plasma;
    globeGroup.add(plasma);

    // --- COMMUNITY ATOMIC NODES (Pioneers) ---
    const createPioneerNode = (position: any, color: number) => {
        const atomGroup = new THREE.Group();
        atomGroup.position.copy(position);

        // Core of the Node
        const coreGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const coreMat = new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: 0.8 });
        const core = new THREE.Mesh(coreGeo, coreMat);
        atomGroup.add(core);

        // Atomic Rings
        for (let i = 0; i < 2; i++) {
            const orbitGeo = new THREE.RingGeometry(0.15, 0.16, 32);
            const orbitMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.2, side: THREE.DoubleSide });
            const orbit = new THREE.Mesh(orbitGeo, orbitMat);
            orbit.rotation.x = Math.random() * Math.PI;
            orbit.rotation.y = Math.random() * Math.PI;

            // Electron Pulse
            const electronGeo = new THREE.SphereGeometry(0.03, 8, 8);
            const electronMat = new THREE.MeshBasicMaterial({ color: 0xffff00 });
            const electron = new THREE.Mesh(electronGeo, electronMat);
            electron.position.x = 0.155;
            orbit.add(electron);

            atomGroup.add(orbit);
        }

        globeGroup.add(atomGroup);
        atomsRef.current.push(atomGroup);
    };

    // Populate global nodes
    Object.values(countryCoords).forEach((coord, i) => {
        const pos = latLonToVector3(coord.lat, coord.lon, RADIUS + 0.2);
        createPioneerNode(pos, 0xffaa00);
    });

    scene.add(globeGroup);

    // --- SOLAR FLARE ATMOSPHERE ---
    const flareGeo = new THREE.SphereGeometry(RADIUS * 1.3, 64, 64);
    const flareMat = new THREE.ShaderMaterial({
        vertexShader: `
            varying vec3 vNormal;
            void main() {
                vNormal = normalize(normalMatrix * normal);
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            varying vec3 vNormal;
            void main() {
                float intensity = pow(0.6 - dot(vNormal, vec3(0, 0, 1.0)), 3.0);
                gl_FragColor = vec4(1.0, 0.5, 0.0, 1.0) * intensity;
            }
        `,
        side: THREE.BackSide,
        blending: THREE.AdditiveBlending,
        transparent: true
    });
    scene.add(new THREE.Mesh(flareGeo, flareMat));

    const animate = () => {
        requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();

        if (globeGroupRef.current) {
            globeGroupRef.current.rotation.y += delta * globeSpeedRef.current * 0.15;
            globeGroupRef.current.rotation.x = Math.sin(time * 0.2) * 0.1;
        }

        // Pulse the Plasma/Mercury Layer
        if (plasmaLayerRef.current) {
            plasmaLayerRef.current.scale.setScalar(1 + Math.sin(time * 3) * 0.02);
            plasmaLayerRef.current.material.opacity = 0.2 + Math.sin(time * 4) * 0.1;
        }

        // Animate Pioneer Nodes (Atomic Jitter)
        atomsRef.current.forEach((atom, i) => {
            atom.children.forEach((child: any, j: number) => {
                if (j > 0) child.rotation.z += delta * (5 + j);
            });
            // Fusion Pulse
            const pulse = 1 + Math.sin(time * 5 + i) * 0.1;
            atom.scale.set(pulse, pulse, pulse);
        });

        renderer.render(scene, camera);
    };
    animate();

    const handleResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };
    window.addEventListener('resize', handleResize);

    return () => {
        window.removeEventListener('resize', handleResize);
        mountRef.current?.removeChild(renderer.domElement);
    };
  }, []);

  return <div ref={mountRef} className="fixed inset-0 z-0 bg-black" />;
};

