const countryCoords: { [key: string]: { lat: number; lon: number, pioneers: string } } = {
  "United States": { lat: 39.82, lon: -98.57, pioneers: "4.2M" },
  "United Kingdom": { lat: 55.37, lon: -3.43, pioneers: "1.8M" },
