const countryNames = Object.keys(countryCoords).sort();

function latLonToVector3(lat: number, lon: number, radius: number) {
    const THREE = window.THREE;
    const phi = (90 - lat) * (Math.PI / 180);
    const theta = (lon + 180) * (Math.PI / 180);
    const x = -(radius * Math.sin(phi) * Math.cos(theta));
    const z = radius * Math.sin(phi) * Math.sin(theta);
    const y = radius * Math.cos(phi);
    return new THREE.Vector3(x, y, z);
}

// --- SHADERS ---
const SunSurfaceShader = {
    uniforms: {
        time: { value: 0.0 },
        color1: { value: null },
        color2: { value: null }
    },
    vertexShader: `
        varying vec2 vUv;
        varying vec3 vNormal;
        void main() {
            vUv = uv;
            vNormal = normalize(normalMatrix * normal);
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `,
    fragmentShader: `
        uniform float time;
        varying vec2 vUv;
        varying vec3 vNormal;

        float noise(vec2 p) {
            return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
        }

        void main() {
            // Intense heat waves
            float brightness = 0.6 + 0.4 * sin(vUv.y * 30.0 + time * 3.5) * cos(vUv.x * 25.0 - time * 2.0);
            brightness += noise(vUv + time * 0.2) * 0.3;

            vec3 coreColor = vec3(1.0, 0.2, 0.0); // Deep red/orange
            vec3 flareColor = vec3(1.0, 0.95, 0.3); // Bright yellow

            vec3 finalColor = mix(coreColor, flareColor, brightness);

            // Fresnel Glow
            float rim = 1.0 - max(dot(vNormal, vec3(0.0, 0.0, 1.0)), 0.0);
            finalColor += flareColor * pow(rim, 2.5) * 3.5;

            gl_FragColor = vec4(finalColor, 1.0);
        }
    `
};

// --- COMPONENTS ---

const ThreeScene: React.FC<{ origin: string; destination: string }> = ({ origin, destination }) => {
    const mountRef = useRef<HTMLDivElement>(null);
    const sceneRef = useRef<any>(null);
    const arcRef = useRef<any>(null);

    useEffect(() => {
        const THREE = window.THREE;
        if (!THREE || !mountRef.current) return;

        const scene = new THREE.Scene();
        sceneRef.current = scene;
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(-2, 0, 11); // Shifted camera to keep sun visible while HUD is on right

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        mountRef.current.appendChild(renderer.domElement);

        const clock = new THREE.Clock();
        const RADIUS = 4.8;

        // --- SUN CORE ---
        const sunGeo = new THREE.SphereGeometry(RADIUS, 64, 64);
        const sunMat = new THREE.ShaderMaterial({
            uniforms: THREE.UniformsUtils.clone(SunSurfaceShader.uniforms),
            vertexShader: SunSurfaceShader.vertexShader,
            fragmentShader: SunSurfaceShader.fragmentShader
        });
        const sun = new THREE.Mesh(sunGeo, sunMat);
        scene.add(sun);

        // --- PIONEER PARTICLE FIELD ---
        const partGeo = new THREE.BufferGeometry();
        const partCount = 3500;
        const posArray = new Float32Array(partCount * 3);
        const colorArray = new Float32Array(partCount * 3);
        for (let i = 0; i < partCount; i++) {
            const r = RADIUS + 0.5 + Math.random() * 15;
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);
            posArray[i * 3] = r * Math.sin(phi) * Math.cos(theta);
            posArray[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
            posArray[i * 3 + 2] = r * Math.cos(phi);

            colorArray[i * 3] = 1.0;
            colorArray[i * 3 + 1] = 0.5 + Math.random() * 0.5;
            colorArray[i * 3 + 2] = 0.0;
        }
        partGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        partGeo.setAttribute('color', new THREE.BufferAttribute(colorArray, 3));
        const partMat = new THREE.PointsMaterial({ 
            size: 0.07, 
            transparent: true, 
            opacity: 0.6, 
            vertexColors: true,
            blending: THREE.AdditiveBlending 
        });
        const particles = new THREE.Points(partGeo, partMat);
        scene.add(particles);

        // --- ATOMIC COUNTRY NODES ---
        const nodeGroup = new THREE.Group();
        Object.values(countryCoords).forEach((c, i) => {
            const pos = latLonToVector3(c.lat, c.lon, RADIUS + 0.15);
            const dotGeo = new THREE.SphereGeometry(0.08, 12, 12);
            const dotMat = new THREE.MeshBasicMaterial({ color: 0xffff00 });
            const dot = new THREE.Mesh(dotGeo, dotMat);
            dot.position.copy(pos);
            nodeGroup.add(dot);

            const ringGeo = new THREE.RingGeometry(0.15, 0.17, 32);
            const ringMat = new THREE.MeshBasicMaterial({ color: 0xffaa00, transparent: true, opacity: 0.3, side: THREE.DoubleSide });
            const ring = new THREE.Mesh(ringGeo, ringMat);
            ring.position.copy(pos);
            ring.lookAt(new THREE.Vector3(0,0,0));
            nodeGroup.add(ring);
        });
        scene.add(nodeGroup);

        const animate = () => {
            requestAnimationFrame(animate);
            const time = clock.getElapsedTime();

            sunMat.uniforms.time.value = time;
            sun.rotation.y += 0.003;
            nodeGroup.rotation.y += 0.003;
            particles.rotation.y -= 0.001;

            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            mountRef.current?.removeChild(renderer.domElement);
        };
    }, []);

    // --- DYNAMIC TRANSIT ARC ---
    useEffect(() => {
        const THREE = window.THREE;
        if (!THREE || !sceneRef.current) return;

        if (arcRef.current) {
            sceneRef.current.remove(arcRef.current);
        }

        const startCoord = countryCoords[origin];
        const endCoord = countryCoords[destination];
        if (!startCoord || !endCoord) return;

        const start = latLonToVector3(startCoord.lat, startCoord.lon, 5.0);
        const end = latLonToVector3(endCoord.lat, endCoord.lon, 5.0);

        const mid = start.clone().lerp(end, 0.5).normalize().multiplyScalar(7.5);
        const curve = new THREE.QuadraticBezierCurve3(start, mid, end);

        const points = curve.getPoints(60);
        const arcGeo = new THREE.BufferGeometry().setFromPoints(points);
        const arcMat = new THREE.LineBasicMaterial({ color: 0x00F2FE, transparent: true, opacity: 0.9, linewidth: 2 });
        const arcLine = new THREE.Line(arcGeo, arcMat);

        const mercuryGeo = new THREE.SphereGeometry(0.12, 16, 16);
        const mercuryMat = new THREE.MeshPhongMaterial({ color: 0xffffff, emissive: 0x00F2FE, shininess: 150 });
        const mercury = new THREE.Mesh(mercuryGeo, mercuryMat);
        arcLine.add(mercury);

        let t = 0;
        const moveMercury = () => {
            t = (t + 0.004) % 1;
            const p = curve.getPointAt(t);
            mercury.position.copy(p.sub(arcLine.position));
            requestAnimationFrame(moveMercury);
        };
        moveMercury();

        arcRef.current = arcLine;
        sceneRef.current.add(arcLine);

    }, [origin, destination]);

    return <div ref={mountRef} className="fixed inset-0 z-0 bg-black pointer-events-none" />;
};

