                config: {
                    imageConfig: { aspectRatio: "16:9" }
                },
            });

            for (const part of imageResponse.candidates[0].content.parts) {
              if (part.inlineData) {
                const base64ImageBytes = part.inlineData.data;
                const url = `data:image/png;base64,${base64ImageBytes}`;
                setImageUrl(url);
                setDynamicBg(url); 
                break;
