  const GUIDE_PROMPT = `
    IDENTITY: VANHSYA_GLOBAL_GUIDE.
    ROLE: You are an elite, world-class digital tour guide for Vanhsya. 
    PERSONALITY: Adventurous, professional, hospitable, and incredibly fast.

    STRICT_CONSTRAINTS:
    - CONCISENESS IS MANDATORY. Limit responses to ONE or TWO brief sentences.
    - NO FILLER WORDS. Get straight to the point.
    - ONLY DISCUSS VANHSYA DATA. If asked about external news, politics, or general web facts, gracefully pivot back to Vanhsya's offerings. Example: "I specialize in our exclusive global expeditions. Would you like to hear about our Dubai Safari instead?"

    VANHSYA_KNOWLEDGE:
    - TOURS: Dubai Desert Safari (AED 275+), Eiffel Tower Summit (AED 360+), Iceland Northern Lights (AED 3400+), Kyoto Blossoms, Serengeti Migration, Machu Picchu, Abu Dhabi Louvre, Jebel Jais Zipline, Hatta Kayaking.
    - REWARDS: VYNO Coin. 14% staking APY.
    - THE BLUEPRINT: Protocol 111 (AED 111), 222 (AED 222 - Recommended), 333 (AED 333 - Elite).
    - NAVIGATE: Use 'navigateTo' for: "/ai-planner", "/treasure-hunt", "/meetups", "/dashboard", "/blogs", "/community".

    LATENCY_INSTRUCTION: Start generating your answer immediately. Do not hesitate.
  `;

  const stopAudio = useCallback(() => {
    audioSourcesRef.current.forEach(source => {
      try { source.stop(); } catch (e) {}
    });
    audioSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsTalking(false);
  }, []);

  const closeSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (scriptProcessorRef.current) {
      scriptProcessorRef.current.disconnect();
      scriptProcessorRef.current = null;
    }
    stopAudio();
    setStatus('IDLE');
  }, [stopAudio]);

  const toggleLink = async () => {
    if (status === 'LIVE' || status === 'SYNCING') {
      closeSession();
      return;
    }

    setStatus('SYNCING');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      if (!inputAudioContextRef.current) {
        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      }
      if (!outputAudioContextRef.current) {
        outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const navigateToTool = {
        name: 'navigateTo',
        parameters: {
          type: Type.OBJECT,
          description: 'Navigates the user to a specific page on the Vanhsya platform.',
          properties: {
            path: { type: Type.STRING, description: 'The internal path, e.g., /ai-planner' },
          },
          required: ['path'],
        },
      };

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setStatus('LIVE');
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
            scriptProcessorRef.current = scriptProcessor;
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'navigateTo') {
                  const path = (fc.args as any).path;
                  navigate(path);
                  sessionPromise.then(s => s.sendToolResponse({
                    functionResponses: { id: fc.id, name: fc.name, response: { result: "REDIRECT_SUCCESS" } }
                  }));
                }
              }
            }
            if (message.serverContent?.outputTranscription) setTranscription(message.serverContent.outputTranscription.text);
            if (message.serverContent?.turnComplete) setTranscription('');

            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              setIsTalking(true);
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) setIsTalking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => { setStatus('ERROR'); closeSession(); },
          onclose: () => { setStatus('IDLE'); closeSession(); },
        },
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [navigateToTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: lang === 'hi' ? 'Kore' : 'Zephyr' } } },
          systemInstruction: GUIDE_PROMPT,
        },
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { setStatus('ERROR'); }
  };

  return (
    <div className="fixed bottom-4 right-4 z-[100] font-mono">
      {!isOpen ? (
        <button 
          onClick={() => setIsOpen(true)}
          className="h-16 w-16 rounded-2xl bg-black border border-[var(--accent-primary)] flex items-center justify-center text-[var(--accent-primary)] shadow-2xl hover:scale-110 transition-all duration-300 group overflow-hidden"
        >
          <div className="absolute inset-0 bg-[var(--accent-primary)] opacity-5 group-hover:opacity-20 transition-opacity"></div>
