};

const PricingOffer: React.FC<{ price: number, currency: string }> = ({ price, currency }) => {
    const offerPrice = parseFloat((price * (CURRENCY_RATES_FROM_USD[currency] || 1)).toFixed(2));
    const originalPrice = parseFloat((offerPrice * 1.18).toFixed(2));
    const savings = parseFloat((originalPrice - offerPrice).toFixed(2));

    const [timeLeft, setTimeLeft] = useState(() => Math.floor(Math.random() * 15 * 60) + 1200);

    useEffect(() => {
        if (timeLeft <= 0) return;
        const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
        return () => clearInterval(timer);
    }, [timeLeft]);

    const minutes = Math.floor(timeLeft / 60);
    const seconds = timeLeft % 60;

    return (
        <div className="mt-10 p-8 rounded-[2.5rem] border-2 shadow-2xl relative overflow-hidden group" style={{ backgroundColor: 'var(--bg-secondary)', borderColor: 'var(--accent-secondary)', boxShadow: '0 0 40px var(--shadow-color-secondary)' }}>
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[var(--accent-secondary)] to-transparent animate-pulse"></div>
            <div className="flex justify-between items-center relative z-10">
                <div>
                    <span className="text-[10px] font-black uppercase tracking-ultra text-zinc-500 mb-2 block">Exclusive Expedition Rate</span>
                    <span className="text-sm line-through text-zinc-500 font-mono mb-1 block">
                        {currency} {originalPrice.toLocaleString()}
                    </span>
                    <div className="text-5xl font-black text-white font-mono leading-none tracking-tight">
                        {currency} {offerPrice.toLocaleString()}
                    </div>
                </div>
                <div className="text-right">
                    <div className="px-5 py-2 bg-green-500/10 border border-green-500/30 text-green-400 rounded-2xl text-xs font-black uppercase tracking-widest shadow-lg">
                        Save {currency} {savings.toLocaleString()}
                    </div>
                </div>
            </div>
            <div className="mt-8 flex items-center justify-center gap-4 py-3 bg-black/40 rounded-2xl border border-white/5">
                <span className="text-[11px] font-black text-zinc-500 uppercase tracking-ultra">Node Access Closes In:</span>
                <span className="font-mono font-black text-xl text-[var(--accent-primary)] tabular-nums tracking-ultra">
                  {String(minutes).padStart(2, '0')}:{String(seconds).padStart(2, '0')}
                </span>
            </div>
        </div>
    );
};


