import React, { useState, useCallback, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Tour } from '@/types';
import { convertFromUSD } from '@/utils/currency';
import { GoogleGenAI } from "@google/genai";

interface TourCardProps {
  tour: Tour;
  currency: string;
}

const ShareIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8.684 13.342C8.886 12.938 9 12.482 9 12s-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.368a3 3 0 105.367 2.684 3 3 0 00-5.367-2.684z" />
  </svg>
);

const SparkleIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" />
  </svg>
);

const TourCard: React.FC<TourCardProps> = ({ tour, currency }) => {
  const displayPrice = tour.displayPrice ?? convertFromUSD(tour.basePriceUSD, currency);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isImageLoaded, setIsImageLoaded] = useState(false);
  const [showCopyFeedback, setShowCopyFeedback] = useState(false);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiImageUrl, setAiImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const img = new Image();
    img.src = tour.images[0];
    const handleLoad = () => setIsImageLoaded(true);
    img.addEventListener('load', handleLoad);
    if (img.complete) handleLoad();
    return () => img.removeEventListener('load', handleLoad);
  }, [tour.images]);

  const handleNextImage = useCallback((e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    if (aiImageUrl) return;
    setCurrentImageIndex((prev) => (prev + 1) % tour.images.length);
  }, [tour.images.length, aiImageUrl]);

  const handlePrevImage = useCallback((e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    if (aiImageUrl) return;
    setCurrentImageIndex((prev) => (prev - 1 + tour.images.length) % tour.images.length);
  }, [tour.images.length, aiImageUrl]);

  const handleAIMagic = async (e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    setIsGeneratingAI(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `A breathtaking, cinematic, 8k professional travel photograph of ${tour.title}. High resolution, award winning composition.`;
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: prompt }] },
            config: { imageConfig: { aspectRatio: "16:9" } }
        });
        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) {
                setAiImageUrl(`data:image/png;base64,${part.inlineData.data}`);
                break;
            }
        }
    } catch (err) { console.error(err); } finally { setIsGeneratingAI(false); }
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    const shareUrl = `${window.location.origin}/#/tours/${tour.slug}`;
    if (navigator.share) {
      try { await navigator.share({ title: `Vanhsya: ${tour.title}`, url: shareUrl }); } catch (err) { console.debug(err); }
    } else {
      try { await navigator.clipboard.writeText(shareUrl); setShowCopyFeedback(true); setTimeout(() => setShowCopyFeedback(false), 2000); } catch (err) { console.error(err); }
    }
  };

  if (!isImageLoaded) {
    return <div className="rounded-[3rem] overflow-hidden flex flex-col border border-zinc-800 animate-pulse bg-zinc-900 h-[600px]"></div>;
  }

  return (
    <div 
      className="group rounded-[3.5rem] overflow-hidden shadow-2xl flex flex-col transform border transition-all duration-1000 hover:-translate-y-4 hover:shadow-[0_40px_100px_rgba(0,0,0,0.6)] hover:border-[var(--accent-primary)]/40"
      style={{ backgroundColor: 'var(--bg-secondary)', borderColor: 'var(--border-color)' }}
    >
      <div className="relative h-80 overflow-hidden">
        {aiImageUrl && (
            <div className="absolute inset-0 z-20 animate-fadeIn">
                <img src={aiImageUrl} alt="AI" className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" />
                <div className="absolute top-6 left-6 bg-black/80 backdrop-blur-xl px-5 py-2 rounded-full text-[10px] text-cyan-400 font-black border border-cyan-500/20 uppercase tracking-[0.3em]">AI Synthesis Active</div>
            </div>
        )}

        {!aiImageUrl && tour.images.map((image, index) => (
          <div
            key={index}
            className="absolute inset-0 w-full h-full bg-cover bg-center transition-all duration-[1500ms] ease-in-out transform group-hover:scale-110"
            style={{ backgroundImage: `url(${image})`, opacity: index === currentImageIndex ? 1 : 0 }}
          />
        ))}

        {isGeneratingAI && (
            <div className="absolute inset-0 z-30 bg-black/80 backdrop-blur-xl flex flex-col items-center justify-center animate-fadeIn">
                <div className="w-16 h-16 border-[4px] border-cyan-500 border-t-transparent rounded-full animate-spin mb-8 shadow-[0_0_30px_var(--accent-primary)]"></div>
                <p className="text-[12px] font-black text-white uppercase tracking-[0.4em] animate-pulse">Synthesizing Imagery...</p>
            </div>
        )}

        <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-1000"></div>

        {!aiImageUrl && (
            <>
                <button onClick={handlePrevImage} className="absolute top-1/2 left-6 -translate-y-1/2 bg-black/60 text-white p-4 rounded-3xl opacity-0 group-hover:opacity-100 transition-all duration-500 hover:bg-cyan-500 hover:text-black z-10"><svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M15 19l-7-7 7-7" strokeWidth={2.5} /></svg></button>
                <button onClick={handleNextImage} className="absolute top-1/2 right-6 -translate-y-1/2 bg-black/60 text-white p-4 rounded-3xl opacity-0 group-hover:opacity-100 transition-all duration-500 hover:bg-cyan-500 hover:text-black z-10"><svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M9 5l7 7-7 7" strokeWidth={2.5} /></svg></button>
            </>
        )}

        <button onClick={handleAIMagic} disabled={isGeneratingAI} className={`absolute top-6 right-6 z-30 p-4 rounded-[1.5rem] backdrop-blur-3xl border border-white/10 text-white transition-all duration-700 hover:scale-110 active:scale-95 group/magic ${aiImageUrl ? 'bg-cyan-500/30 text-cyan-400 border-cyan-400/30' : 'bg-black/70 hover:bg-cyan-500 hover:text-black'}`} title="AI Synthesis"><SparkleIcon /></button>

        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex space-x-3 z-10">
          {!aiImageUrl && tour.images.map((_, index) => (
            <button key={index} onClick={(e) => { e.preventDefault(); e.stopPropagation(); setCurrentImageIndex(index); }} className={`h-1 rounded-full transition-all duration-700 ${index === currentImageIndex ? 'bg-cyan-400 w-10 shadow-[0_0_15px_#00f2fe]' : 'bg-white/20 w-2 hover:bg-white/50'}`} />
          ))}
        </div>
      </div>

      <div className="p-10 md:p-12 flex-1 flex flex-col">
        <p className="text-[12px] font-black uppercase tracking-[0.4em] text-[var(--accent-primary)] opacity-70 mb-4">{tour.city}, {tour.country}</p>
        <h3 className="font-black text-3xl md:text-4xl font-cinzel leading-[0.95] group-hover:text-[var(--accent-primary)] transition-colors tracking-tight-titles mb-6" style={{ color: 'var(--text-primary)'}}>{tour.title}</h3>
        <p className="text-lg mt-2 line-clamp-3 flex-grow leading-relaxed font-light text-zinc-400 italic" style={{ color: 'var(--text-secondary)'}}>{tour.description}</p>

        <div className="mt-12 pt-10 border-t border-white/5 flex items-center justify-between">
          <div className="flex flex-col">
              <span className="text-[11px] text-zinc-600 font-black uppercase tracking-luxury mb-2">Protocol Entry At</span>
              <span className="font-black text-3xl text-white font-mono leading-none">{currency} {displayPrice.toLocaleString()}</span>
          </div>

          <div className="flex items-center gap-4">
            <button onClick={handleShare} className="p-4 rounded-[1.5rem] border border-white/5 hover:bg-white/5 transition-all relative group/shareBtn" title="Share Mission"><ShareIcon />{showCopyFeedback && <div className="absolute -top-14 left-1/2 -translate-x-1/2 bg-green-500 text-black text-[10px] font-black px-4 py-2 rounded-xl shadow-2xl animate-bounce tracking-widest uppercase">Copied</div>}</button>
            <Link className="px-10 py-5 rounded-[1.5rem] text-black text-[12px] font-black uppercase tracking-luxury transition-all transform hover:scale-110 hover:shadow-[0_15px_40px_rgba(0,242,254,0.4)] active:scale-95" to={`/tours/${tour.slug}`} style={{ backgroundColor: 'var(--accent-primary)' }}>Synchronize</Link>
          </div>
        </div>
      </div>
    </div>
  );
};

