const GuideBot: React.FC = () => {
  const navigate = useNavigate();
  const { lang } = useAppContext();
  const [isOpen, setIsOpen] = useState(false);
  const [status, setStatus] = useState<'IDLE' | 'SYNCING' | 'LIVE' | 'ERROR'>('IDLE');
  const [isTalking, setIsTalking] = useState(false);
  const [transcription, setTranscription] = useState('');

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);

  const PROMPT = `IDENTITY: VANHSYA_CONCIERGE. ROLE: Elite digital guide for high-end global travel architecture. PERSONALITY: Professional, refined, hospitable, ultra-fast. CONSTRAINTS: Max 2 sentences. Use 'navigateTo' for site navigation. KNOWS: All TOURS, VYNO rewards, AI Planner, VR Experience, The Blueprint.`;

  const stopAudio = useCallback(() => {
    audioSourcesRef.current.forEach(s => { try { s.stop(); } catch {} });
    audioSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsTalking(false);
  }, []);

  const closeSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    stopAudio(); setStatus('IDLE');
  }, [stopAudio]);

  const toggleLink = async () => {
    if (status === 'LIVE' || status === 'SYNCING') { closeSession(); return; }
    setStatus('SYNCING');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      if (!inputAudioContextRef.current) inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      if (!outputAudioContextRef.current) outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const navTool = { name: 'navigateTo', parameters: { type: Type.OBJECT, properties: { path: { type: Type.STRING } }, required: ['path'] } };
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setStatus('LIVE');
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const sp = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            sp.onaudioprocess = (e) => sessionPromise.then(s => s.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) }));
            source.connect(sp); sp.connect(inputAudioContextRef.current!.destination);
            scriptProcessorRef.current = sp;
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.toolCall) m.toolCall.functionCalls.forEach(fc => { if (fc.name === 'navigateTo') { navigate((fc.args as any).path); sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "OK" } } })); } });
            if (m.serverContent?.outputTranscription) setTranscription(m.serverContent.outputTranscription.text);
            if (m.serverContent?.turnComplete) setTranscription('');
            const data = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (data) {
              setIsTalking(true); const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buf = await decodeAudioData(decode(data), ctx, 24000, 1);
              const s = ctx.createBufferSource(); s.buffer = buf; s.connect(ctx.destination);
              s.onended = () => { audioSourcesRef.current.delete(s); if (audioSourcesRef.current.size === 0) setIsTalking(false); };
              s.start(nextStartTimeRef.current); nextStartTimeRef.current += buf.duration; audioSourcesRef.current.add(s);
            }
            if (m.serverContent?.interrupted) stopAudio();
          },
          onerror: () => { setStatus('ERROR'); closeSession(); },
          onclose: () => { setStatus('IDLE'); closeSession(); },
        },
        config: { responseModalities: [Modality.AUDIO], tools: [{ functionDeclarations: [navTool] }], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } }, systemInstruction: PROMPT },
      });
      sessionRef.current = await sessionPromise;
    } catch { setStatus('ERROR'); }
  };

  return (
    <div className="fixed bottom-8 right-8 z-[100] font-mono">
      {!isOpen ? (
        <button onClick={() => setIsOpen(true)} className="h-20 w-20 rounded-[2rem] bg-black border border-[var(--accent-primary)]/40 flex items-center justify-center text-[var(--accent-primary)] shadow-4xl hover:scale-110 transition-all duration-500 group overflow-hidden">
          <div className="absolute inset-0 bg-[var(--accent-primary)] opacity-5 group-hover:opacity-20 transition-opacity"></div>
          <svg className="w-10 h-10 animate-pulse" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/><circle cx="12" cy="9" r="2.5"/></svg>
        </button>
      ) : (
        <div className="w-[320px] sm:w-[400px] bg-zinc-950/98 backdrop-blur-3xl border border-white/10 rounded-[3.5rem] shadow-[0_0_100px_rgba(0,0,0,0.8)] flex flex-col overflow-hidden animate-fadeIn border-t-[var(--accent-primary)]/30 relative">
          <MetatronCube />
          <div className="p-8 border-b border-white/5 flex items-center justify-between bg-black/40 relative z-10">
            <div className="flex items-center gap-5">
              <div className={`p-3 rounded-2xl bg-black border border-white/10 text-[var(--accent-primary)] transition-all ${isTalking ? 'shadow-[0_0_20px_var(--accent-primary)]' : ''}`}><span className="text-2xl">🎩</span></div>
              <div className="flex flex-col">
                <span className="text-[12px] text-white font-black uppercase tracking-luxury">Vanhsya Concierge</span>
                <div className="flex items-center gap-2 mt-1">
                  <span className={`w-2 h-2 rounded-full ${status === 'LIVE' ? 'bg-green-500 animate-pulse shadow-[0_0_10px_#22c55e]' : status === 'ERROR' ? 'bg-red-500' : status === 'SYNCING' ? 'bg-blue-500 animate-pulse' : 'bg-zinc-700'}`}></span>
                  <span className="text-[10px] text-gray-500 font-black uppercase tracking-luxury">{status === 'LIVE' ? 'Secure Link' : status}</span>
                </div>
              </div>
            </div>
            <button onClick={() => { closeSession(); setIsOpen(false); }} className="text-gray-600 hover:text-white transition-all p-3 hover:bg-white/5 rounded-2xl"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          </div>
          <div className="flex-1 p-12 flex flex-col items-center justify-center gap-10 relative z-10">
            <GenesisOrb state={isTalking ? 'TALKING' : status === 'SYNCING' ? 'SYNCING' : status === 'LIVE' ? 'ACTIVE' : 'IDLE'} />
            <div className="h-14 text-center px-6 overflow-hidden">
              {transcription ? <p className="text-[13px] text-[var(--accent-primary)] font-black italic animate-fadeIn line-clamp-2 leading-relaxed">"{transcription}"</p> : <p className="text-[10px] text-gray-600 font-black uppercase tracking-luxury opacity-40">Private Architect Access</p>}
            </div>
            <button onClick={toggleLink} className={`h-28 w-28 rounded-full border-2 flex flex-col items-center justify-center transition-all duration-700 relative group/btn ${status === 'LIVE' ? 'bg-cyan-950/20 border-cyan-400 text-cyan-400 scale-105 shadow-[0_0_50px_rgba(6,182,212,0.4)]' : status === 'SYNCING' ? 'bg-zinc-900 border-yellow-600 text-yellow-500' : 'bg-black border-white/10 text-white hover:border-[var(--accent-primary)] hover:text-[var(--accent-primary)]'}`}>
              <svg className={`w-12 h-12 mb-1 transition-transform ${status === 'LIVE' ? 'scale-110' : 'group-hover/btn:scale-125'}`} fill="currentColor" viewBox="0 0 24 24">{status === 'LIVE' ? <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zM17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/> : <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5a2.5 2.5 0 010-5 2.5 2.5 0 010 5z"/>}</svg>
              <span className="text-[10px] font-black uppercase tracking-luxury">{status === 'LIVE' ? 'Linked' : 'Initialize'}</span>
            </button>
            <div className="w-full space-y-5">
              <div className="flex justify-between items-center text-[9px] text-gray-800 font-black uppercase tracking-luxury"><span>Concierge Protocol: v9.0</span><span>Link: {status === 'LIVE' ? 'Solid' : '--'}</span></div>
              <div className="h-1 w-full bg-white/5 rounded-full overflow-hidden border border-white/5"><div className={`h-full bg-[var(--accent-primary)] transition-all duration-1000 ${isTalking ? 'w-full shadow-[0_0_20px_#fff]' : 'w-0'}`}></div></div>
            </div>
          </div>
          <div className="bg-black/60 py-4 px-10 text-[9px] font-black uppercase tracking-luxury flex justify-between items-center opacity-60 border-t border-white/5 relative z-10">
            <span className="text-[var(--accent-primary)]">Verified Vanhsya Node</span><span className="text-gray-800">Elite Expertise</span>
          </div>
        </div>
      )}
    </div>
  );
};

