import React, { useState, useCallback, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Tour } from '@/types';
import { convertFromUSD } from '@/utils/currency';
import { GoogleGenAI } from "@google/genai";

interface TourCardProps {
  tour: Tour;
  currency: string;
}

const TourCard: React.FC<TourCardProps> = ({ tour, currency }) => {
  const displayPrice = tour.displayPrice ?? convertFromUSD(tour.basePriceUSD, currency);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isImageLoaded, setIsImageLoaded] = useState(false);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiImageUrl, setAiImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const img = new Image();
    img.src = tour.images[0];
    img.onload = () => setIsImageLoaded(true);
  }, [tour.images]);

  const handleAIMagic = async (e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    setIsGeneratingAI(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Cinematic, hyper-realistic, luxury 8k travel photography of ${tour.title} in ${tour.city}. Beautiful lighting, professional composition.`;
        const resp = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: prompt }] },
            config: { imageConfig: { aspectRatio: "16:9" } }
        });
        for (const part of resp.candidates[0].content.parts) {
            if (part.inlineData) {
                setAiImageUrl(`data:image/png;base64,${part.inlineData.data}`);
                break;
            }
        }
    } catch (err) { console.error(err); } finally { setIsGeneratingAI(false); }
  };

  if (!isImageLoaded) return <div className="rounded-[3.5rem] border border-white/5 animate-pulse bg-zinc-900 h-[650px]"></div>;

  return (
    <div className="group rounded-[4rem] overflow-hidden shadow-2xl flex flex-col transform border transition-all duration-[1.5s] hover:-translate-y-6 hover:shadow-[0_60px_120px_rgba(0,0,0,0.8)] hover:border-white/20 bg-[var(--bg-secondary)] border-white/5">
      <div className="relative h-96 overflow-hidden">
        {aiImageUrl ? (
            <div className="absolute inset-0 z-20 animate-fadeIn">
                <img src={aiImageUrl} className="w-full h-full object-cover" />
                <div className="absolute top-8 left-8 bg-black/80 backdrop-blur-3xl px-6 py-2 rounded-full text-[10px] text-cyan-400 font-black border border-white/10 uppercase tracking-[0.4em]">AI Synthesised</div>
            </div>
        ) : tour.images.map((image, idx) => (
          <div key={idx} className="absolute inset-0 w-full h-full bg-cover bg-center transition-all duration-[2s] group-hover:scale-110" style={{ backgroundImage: `url(${image})`, opacity: idx === currentImageIndex ? 1 : 0 }} />
        ))}

        {isGeneratingAI && (
            <div className="absolute inset-0 z-30 bg-black/80 backdrop-blur-2xl flex flex-col items-center justify-center">
                <div className="w-16 h-16 border-[4px] border-cyan-500 border-t-transparent rounded-full animate-spin mb-8"></div>
                <p className="text-[11px] font-black text-white uppercase tracking-[0.4em] animate-pulse">Synchronising Imagery...</p>
            </div>
        )}

        <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-1000"></div>

        <button onClick={handleAIMagic} disabled={isGeneratingAI} className="absolute top-8 right-8 z-30 p-5 rounded-[1.5rem] backdrop-blur-3xl border border-white/10 text-white transition-all duration-700 hover:scale-110 active:scale-95 bg-black/60 hover:bg-cyan-500 hover:text-black">
            ✨
        </button>

        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex space-x-3 z-10">
          {!aiImageUrl && tour.images.map((_, idx) => (
            <button key={idx} onClick={(e) => { e.preventDefault(); e.stopPropagation(); setCurrentImageIndex(idx); }} className={`h-1 rounded-full transition-all duration-1000 ${idx === currentImageIndex ? 'bg-cyan-400 w-12 shadow-[0_0_20px_#00f2fe]' : 'bg-white/20 w-3 hover:bg-white/50'}`} />
          ))}
        </div>
      </div>

      <div className="p-12 md:p-14 flex-1 flex flex-col">
        <p className="text-[11px] font-black uppercase tracking-[0.4em] text-[var(--accent-primary)] mb-6 font-mono">{tour.city}, {tour.country}</p>
        <h3 className="font-black text-4xl md:text-5xl font-cinzel leading-[0.95] group-hover:text-[var(--accent-primary)] transition-colors tracking-tight-titles mb-8 text-white">{tour.title}</h3>
        <p className="text-xl mt-2 line-clamp-3 flex-grow leading-relaxed font-light text-zinc-400 italic font-opensans opacity-90">{tour.description}</p>

        <div className="mt-14 pt-12 border-t border-white/5 flex items-center justify-between">
          <div className="flex flex-col">
              <span className="text-[10px] text-zinc-600 font-black uppercase tracking-luxury mb-2 font-roboto">Protocol Baseline</span>
              <span className="font-black text-4xl text-white font-mono leading-none tracking-tighter">{currency} {displayPrice.toLocaleString()}</span>
          </div>
          <Link className="px-14 py-6 rounded-3xl text-black text-[12px] font-black uppercase tracking-luxury transition-all transform hover:scale-110 hover:shadow-[0_20px_60px_rgba(0,242,254,0.4)] active:scale-95 font-roboto" to={`/tours/${tour.slug}`} style={{ backgroundColor: 'var(--accent-primary)' }}>Synchronise</Link>
        </div>
      </div>
    </div>
  );
};

export default TourCard;

