import React, { useState, useCallback, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Tour } from '@/types';
import { convertFromUSD } from '@/utils/currency';
import { GoogleGenAI } from "@google/genai";

interface TourCardProps {
  tour: Tour;
  currency: string;
}

const TourCard: React.FC<TourCardProps> = ({ tour, currency }) => {
  const displayPrice = tour.displayPrice ?? convertFromUSD(tour.basePriceUSD, currency);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isImageLoaded, setIsImageLoaded] = useState(false);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiImageUrl, setAiImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const img = new Image();
    img.src = tour.images[0];
    img.onload = () => setIsImageLoaded(true);
    if (img.complete) setIsImageLoaded(true);
  }, [tour.images]);

  const handleAIMagic = async (e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    setIsGeneratingAI(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Luxurious, cinematic travel photograph of ${tour.title} in ${tour.city}. Beautiful natural lighting, 8k resolution, professional composition, atmospheric depth.`;
        const resp = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: prompt }] },
            config: { imageConfig: { aspectRatio: "16:9" } }
        });
        for (const part of resp.candidates[0].content.parts) {
            if (part.inlineData) {
                setAiImageUrl(`data:image/png;base64,${part.inlineData.data}`);
                break;
            }
        }
    } catch (err) { console.error(err); } finally { setIsGeneratingAI(false); }
  };

  if (!isImageLoaded) return <div className="rounded-[3.5rem] border border-white/5 animate-pulse bg-zinc-900 h-[680px]"></div>;

  return (
    <div className="group rounded-[4rem] overflow-hidden shadow-3xl flex flex-col transform border transition-all duration-[1.5s] hover:-translate-y-8 hover:shadow-[0_80px_160px_rgba(0,0,0,0.8)] hover:border-white/20 bg-[var(--bg-secondary)] border-white/5">
      <div className="relative h-[400px] overflow-hidden">
        {aiImageUrl ? (
            <div className="absolute inset-0 z-20 animate-fadeIn">
                <img src={aiImageUrl} className="w-full h-full object-cover transition-transform duration-[3000ms] group-hover:scale-110" />
                <div className="absolute top-10 left-10 bg-black/80 backdrop-blur-3xl px-8 py-2 rounded-full text-[10px] text-cyan-400 font-black border border-cyan-500/20 uppercase tracking-[0.4em]">Neural Link: Synthesised</div>
            </div>
        ) : tour.images.map((image, idx) => (
          <div key={idx} className="absolute inset-0 w-full h-full bg-cover bg-center transition-all duration-[2.5s] group-hover:scale-110" style={{ backgroundImage: `url(${image})`, opacity: idx === currentImageIndex ? 1 : 0 }} />
        ))}

        {isGeneratingAI && (
            <div className="absolute inset-0 z-30 bg-black/90 backdrop-blur-2xl flex flex-col items-center justify-center">
                <div className="w-16 h-16 border-[4px] border-cyan-500 border-t-transparent rounded-full animate-spin mb-10 shadow-[0_0_30px_#00f2fe]"></div>
                <p className="text-[11px] font-black text-white uppercase tracking-[0.5em] animate-pulse">Establishing Neural Vision...</p>
            </div>
        )}

        <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-1000"></div>

        <button onClick={handleAIMagic} disabled={isGeneratingAI} className="absolute top-10 right-10 z-30 p-6 rounded-[2rem] backdrop-blur-3xl border border-white/10 text-white transition-all duration-700 hover:scale-110 active:scale-95 bg-black/60 hover:bg-cyan-500 hover:text-black shadow-2xl">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>
        </button>

        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex space-x-4 z-10">
          {!aiImageUrl && tour.images.map((_, idx) => (
            <button key={idx} onClick={(e) => { e.preventDefault(); e.stopPropagation(); setCurrentImageIndex(idx); }} className={`h-1 rounded-full transition-all duration-1000 ${idx === currentImageIndex ? 'bg-cyan-400 w-16 shadow-[0_0_20px_#00f2fe]' : 'bg-white/20 w-4 hover:bg-white/50'}`} />
          ))}
        </div>
      </div>

      <div className="p-14 md:p-16 flex-1 flex flex-col">
        <p className="text-[12px] font-black uppercase tracking-[0.4em] text-[var(--accent-primary)] mb-8 font-mono opacity-80">{tour.city}, {tour.country} /// {tour.durationHours}HR MISSION</p>
        <h3 className="font-black text-4xl md:text-6xl font-cinzel leading-[0.9] group-hover:text-[var(--accent-primary)] transition-colors tracking-tight-titles mb-10 text-white uppercase">{tour.title}</h3>
        <p className="text-xl mt-2 line-clamp-3 flex-grow leading-relaxed font-light text-zinc-400 italic font-opensans opacity-95">{tour.description}</p>

        <div className="mt-20 pt-14 border-t border-white/5 flex items-center justify-between">
          <div className="flex flex-col">
              <span className="text-[11px] text-zinc-600 font-black uppercase tracking-luxury mb-3 font-roboto">Privateer Protocol Baseline</span>
              <span className="font-black text-5xl text-white font-mono leading-none tracking-tighter drop-shadow-lg">{currency} {displayPrice.toLocaleString()}</span>
          </div>
          <Link className="px-16 py-7 rounded-[2rem] text-black text-[14px] font-black uppercase tracking-luxury transition-all transform hover:scale-110 hover:shadow-[0_25px_80px_rgba(0,242,254,0.5)] active:scale-95 font-roboto" to={`/tours/${tour.slug}`} style={{ backgroundColor: 'var(--accent-primary)' }}>Establish Link</Link>
        </div>
      </div>
    </div>
  );
};

