const PricingOffer: React.FC<{ price: number, currency: string }> = ({ price, currency }) => {
    const offerPrice = parseFloat((price * (CURRENCY_RATES_FROM_USD[currency] || 1)).toFixed(2));
    const originalPrice = parseFloat((offerPrice * 1.25).toFixed(2));
    const savings = parseFloat((originalPrice - offerPrice).toFixed(2));
    const [timeLeft, setTimeLeft] = useState(1440);

    useEffect(() => {
        const timer = setInterval(() => setTimeLeft(p => Math.max(0, p - 1)), 1000);
        return () => clearInterval(timer);
    }, []);

    const mm = Math.floor(timeLeft / 60);
    const ss = timeLeft % 60;

    return (
        <div className="mt-14 p-12 rounded-[3.5rem] border-2 shadow-2xl relative overflow-hidden group" style={{ backgroundColor: 'var(--bg-secondary)', borderColor: 'var(--accent-secondary)', boxShadow: '0 0 60px var(--shadow-color-secondary)' }}>
            <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-transparent via-[var(--accent-secondary)] to-transparent animate-pulse"></div>
            <div className="flex justify-between items-center relative z-10">
                <div>
                    <span className="text-[12px] font-black uppercase tracking-luxury text-zinc-500 mb-4 block">Exclusive Protocol Rate</span>
                    <span className="text-xl line-through text-zinc-600 font-mono mb-2 block opacity-60">
                        {currency} {originalPrice.toLocaleString()}
                    </span>
                    <div className="text-6xl md:text-7xl font-black text-white font-mono leading-none tracking-tight">
                        {currency} {offerPrice.toLocaleString()}
                    </div>
                </div>
                <div className="text-right hidden sm:block">
                    <div className="px-8 py-3 bg-green-500/10 border border-green-500/40 text-green-400 rounded-[1.5rem] text-[12px] font-black uppercase tracking-luxury shadow-2xl">
                        Synthesized Yield: {currency} {savings.toLocaleString()}
                    </div>
                </div>
            </div>
            <div className="mt-12 flex items-center justify-center gap-6 py-4 bg-black/60 rounded-[2rem] border border-white/5">
                <span className="text-[13px] font-black text-zinc-500 uppercase tracking-luxury">Node Lock Expiry:</span>
                <span className="font-mono font-black text-3xl text-[var(--accent-primary)] tabular-nums tracking-luxury drop-shadow-0_0_10px_#00f2fe">
                  {String(mm).padStart(2, '0')}:{String(ss).padStart(2, '0')}
                </span>
            </div>
        </div>
    );
};

