import React, { useState, useCallback, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Tour } from '@/types';
import { convertFromUSD } from '@/utils/currency';
import { GoogleGenAI } from "@google/genai";

interface TourCardProps {
  tour: Tour;
  currency: string;
}

const TourCard: React.FC<TourCardProps> = ({ tour, currency }) => {
  const displayPrice = tour.displayPrice ?? convertFromUSD(tour.basePriceUSD, currency);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isImageLoaded, setIsImageLoaded] = useState(false);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiImageUrl, setAiImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const img = new Image();
    img.src = tour.images[0];
    img.onload = () => setIsImageLoaded(true);
    if (img.complete) setIsImageLoaded(true);
  }, [tour.images]);

  const handleAIMagic = async (e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    setIsGeneratingAI(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Highly cinematic, hyper-realistic, luxury travel photograph of ${tour.title} in ${tour.city}. Professional lighting, 8k resolution, award-winning composition, wide-angle atmospheric depth.`;
        const resp = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: prompt }] },
            config: { imageConfig: { aspectRatio: "16:9" } }
        });
        for (const part of resp.candidates[0].content.parts) {
            if (part.inlineData) {
                setAiImageUrl(`data:image/png;base64,${part.inlineData.data}`);
                break;
            }
        }
    } catch (err) { console.error(err); } finally { setIsGeneratingAI(false); }
  };

  if (!isImageLoaded) return <div className="rounded-[4rem] border border-white/5 animate-pulse bg-zinc-900/50 h-[750px]"></div>;

  return (
    <div className="group rounded-[4.5rem] overflow-hidden shadow-4xl flex flex-col transform border transition-all duration-[2s] hover:-translate-y-10 hover:shadow-[0_100px_200px_rgba(0,0,0,0.85)] hover:border-white/20 bg-[#08080C] border-white/5">
      <div className="relative h-[480px] overflow-hidden">
        {aiImageUrl ? (
            <div className="absolute inset-0 z-20 animate-fadeIn">
                <img src={aiImageUrl} className="w-full h-full object-cover transition-transform duration-[4000ms] group-hover:scale-110" />
                <div className="absolute top-12 left-12 bg-black/80 backdrop-blur-3xl px-10 py-3 rounded-full text-[11px] text-cyan-400 font-black border border-cyan-500/30 uppercase tracking-[0.5em] font-roboto">Neural Link: Synthesised</div>
            </div>
        ) : tour.images.map((image, idx) => (
          <div key={idx} className="absolute inset-0 w-full h-full bg-cover bg-center transition-all duration-[3s] group-hover:scale-110" style={{ backgroundImage: `url(${image})`, opacity: idx === currentImageIndex ? 1 : 0 }} />
        ))}

        {isGeneratingAI && (
            <div className="absolute inset-0 z-30 bg-black/95 backdrop-blur-3xl flex flex-col items-center justify-center">
                <div className="w-20 h-20 border-[5px] border-cyan-500 border-t-transparent rounded-full animate-spin mb-14 shadow-[0_0_50px_#00f2fe]"></div>
                <p className="text-[12px] font-black text-white uppercase tracking-[0.6em] animate-pulse font-roboto">Aligning Neural Matrix...</p>
            </div>
        )}

        <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-1500"></div>

        <button onClick={handleAIMagic} disabled={isGeneratingAI} className="absolute top-12 right-12 z-30 p-8 rounded-[2.5rem] backdrop-blur-3xl border border-white/10 text-white transition-all duration-1000 hover:scale-110 active:scale-95 bg-black/60 hover:bg-cyan-500 hover:text-black shadow-3xl ring-1 ring-white/10">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>
        </button>

        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex space-x-5 z-10">
          {!aiImageUrl && tour.images.map((_, idx) => (
            <button key={idx} onClick={(e) => { e.preventDefault(); e.stopPropagation(); setCurrentImageIndex(idx); }} className={`h-1 rounded-full transition-all duration-[1.5s] ${idx === currentImageIndex ? 'bg-cyan-400 w-20 shadow-[0_0_30px_#00f2fe]' : 'bg-white/10 w-5 hover:bg-white/40'}`} />
          ))}
        </div>
      </div>

      <div className="p-16 md:p-20 flex-1 flex flex-col font-opensans">
        <p className="text-[14px] font-black uppercase tracking-[0.5em] text-[var(--accent-primary)] mb-10 font-roboto opacity-80">{tour.city}, {tour.country} /// {tour.durationHours}HR MISSION</p>
        <h3 className="font-black text-5xl md:text-7xl font-cinzel leading-[0.85] group-hover:text-[var(--accent-primary)] transition-colors tracking-tight-titles mb-12 text-white uppercase">{tour.title}</h3>
        <p className="text-2xl mt-2 line-clamp-3 flex-grow leading-relaxed font-light text-zinc-400 italic opacity-95 border-l-4 border-white/5 pl-10">{tour.description}</p>

        <div className="mt-24 pt-16 border-t border-white/5 flex items-center justify-between">
          <div className="flex flex-col">
              <span className="text-[12px] text-zinc-600 font-black uppercase tracking-luxury mb-4 font-roboto">Privateer Protocol Base</span>
              <span className="font-black text-6xl text-white font-mono leading-none tracking-tighter drop-shadow-2xl">{currency} {displayPrice.toLocaleString()}</span>
          </div>
          <Link className="px-20 py-8 rounded-[2.5rem] text-black text-[16px] font-black uppercase tracking-[0.5em] transition-all transform hover:scale-110 hover:shadow-[0_30px_100px_rgba(0,242,254,0.5)] active:scale-95 font-roboto" to={`/tours/${tour.slug}`} style={{ backgroundColor: 'var(--accent-primary)' }}>Establish Link</Link>
        </div>
      </div>
    </div>
  );
};

export default TourCard;

