                            {isGeneratingVideo && (
                                <div className="absolute inset-0 bg-black/70 backdrop-blur-md flex flex-col items-center justify-center text-center p-10">
                                    <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mb-6 shadow-[0_0_30px_rgba(0,242,254,0.5)]"></div>
                                    <p className="text-cyan-400 font-mono font-black text-sm uppercase tracking-luxury animate-pulse">{videoStatus}</p>
                                    <p className="mt-4 text-[10px] text-zinc-500 uppercase tracking-widest">Veo 3.1 Neural Processing Active</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>
                <div className="grid grid-cols-4 gap-4">
                  {tour.images.map((img, i) => (
                    <button key={i} onClick={() => { setSelectedImage(img); setVideoUrl(null); }} className={`rounded-3xl overflow-hidden border-2 transition-all duration-700 ${selectedImage === img && !videoUrl ? 'border-[var(--accent-primary)] scale-105' : 'border-transparent hover:border-white/20'}`}>
                        <img src={img} alt="thumb" className="w-full h-24 object-cover" />
                    </button>
                  ))}
                </div>
              </div>
            </AnimateOnScroll>
          </div>

          <div className="lg:col-span-5">
