    if (!hasKey) {
        await window.aistudio.openSelectKey();
    }

    setIsGeneratingVideo(true);
    setVideoStatus('Initializing Neural Renderer...');

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const prompt = `A cinematic, hyper-realistic drone flyover of ${tour.city} showcasing ${tour.title}. High-fidelity lighting, 4k detail, epic atmospheric depth. The video should feel like a premium luxury travel mission briefing.`;

        setVideoStatus('Aligning Global Asset Nodes...');
        let operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt,
            config: {
                numberOfVideos: 1,
                resolution: '720p',
                aspectRatio: '16:9'
            }
        });

        while (!operation.done) {
            setVideoStatus(`Rendering Frame Matrix: ${Math.floor(Math.random() * 30 + 10)}% Sync...`);
            await new Promise(resolve => setTimeout(resolve, 8000));
            operation = await ai.operations.getVideosOperation({ operation });
        }

        setVideoStatus('Finalizing Stream Link...');
        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
