                </div>
            </AnimateOnScroll>

            <AnimateOnScroll>
                <div className="rounded-[4rem] overflow-hidden border border-white/5 shadow-4xl h-[600px] relative">
                    <InteractiveMap centerLat={tour.latitude} centerLng={tour.longitude} zoom={13} markers={tourMarker} />
