import AnimateOnScroll from '@/components/AnimateOnScroll';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    marked: any;
    aistudio: AIStudio;
  }
}

const CheckIcon = () => <svg className="w-5 h-5 text-green-500 flex-shrink-0 mt-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M5 13l4 4L19 7" strokeWidth={3} /></svg>;
const CrossIcon = () => <svg className="w-5 h-5 text-red-500 flex-shrink-0 mt-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M6 18L18 6M6 6l12 12" strokeWidth={3} /></svg>;

const ItineraryAccordion: React.FC<{ items: ItineraryItem[] }> = ({ items }) => {
    const [openIndex, setOpenIndex] = useState<number | null>(0);
    return (
        <div className="space-y-4">
            {items.map((item, index) => (
                <div key={index} className="rounded-[1.5rem] overflow-hidden border transition-all duration-700" style={{ borderColor: 'var(--border-color)', backgroundColor: 'var(--bg-secondary)' }}>
                    <button onClick={() => setOpenIndex(openIndex === index ? null : index)} className="w-full flex justify-between items-center p-5 text-left group">
                        <span className="font-bold text-base font-cinzel tracking-tight uppercase transition-colors group-hover:text-[var(--accent-secondary)]">
                          <span className="text-[var(--accent-secondary)] opacity-50 mr-4 font-mono text-xs">NODE 0{index + 1}</span> {item.title}
                        </span>
                        <svg className={`w-5 h-5 transform transition-transform duration-700 text-[var(--accent-secondary)] ${openIndex === index ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M19 9l-7 7-7-7" strokeWidth={3} /></svg>
                    </button>
                    <div className={`transition-all duration-700 ease-in-out overflow-hidden ${openIndex === index ? 'max-h-[600px] opacity-100' : 'max-h-0 opacity-0'}`}>
                        <div className="p-6 pt-0 text-sm leading-relaxed text-zinc-400 font-light italic">
                            {item.description}
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
};

const PricingOffer: React.FC<{ price: number, currency: string }> = ({ price, currency }) => {
    const offerPrice = parseFloat((price * (CURRENCY_RATES_FROM_USD[currency] || 1)).toFixed(2));
    const originalPrice = parseFloat((offerPrice * 1.25).toFixed(2));
    const savings = parseFloat((originalPrice - offerPrice).toFixed(2));
    const [timeLeft, setTimeLeft] = useState(1440);

    useEffect(() => {
        const timer = setInterval(() => setTimeLeft(p => Math.max(0, p - 1)), 1000);
        return () => clearInterval(timer);
    }, []);

    const mm = Math.floor(timeLeft / 60);
    const ss = timeLeft % 60;

    return (
        <div className="mt-8 p-8 rounded-[2rem] border shadow-xl relative overflow-hidden group" style={{ backgroundColor: 'var(--bg-secondary)', borderColor: 'var(--border-color)' }}>
            <div className="absolute top-0 left-0 w-full h-0.5 bg-gradient-to-r from-transparent via-[var(--accent-secondary)] to-transparent animate-pulse"></div>
            <div className="flex justify-between items-center relative z-10">
                <div>
                    <span className="text-[9px] font-black uppercase tracking-widest text-zinc-500 mb-2 block">High Fidelity Matrix Rate</span>
                    <span className="text-sm line-through text-zinc-600 font-mono block opacity-60">
                        {currency} {originalPrice.toLocaleString()}
                    </span>
                    <div className="text-4xl md:text-5xl font-black text-white font-mono leading-none tracking-tighter">
                        {currency} {offerPrice.toLocaleString()}
                    </div>
                </div>
                <div className="text-right hidden sm:block">
                    <div className="px-5 py-2 bg-green-500/10 border border-green-500/30 text-green-400 rounded-full text-[9px] font-black uppercase tracking-widest">
                        Protocol Yield: {currency} {savings.toLocaleString()}
                    </div>
                </div>
            </div>
            <div className="mt-6 flex items-center justify-center gap-3 py-2.5 bg-black/40 rounded-xl border border-white/5">
                <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Link Lock Expiry:</span>
                <span className="font-mono font-black text-lg text-[var(--accent-primary)] tabular-nums tracking-widest">
                  {String(mm).padStart(2, '0')}:{String(ss).padStart(2, '0')}
                </span>
            </div>
        </div>
    );
};

