                        </span>
                        <svg className={`w-6 h-6 transform transition-transform duration-700 text-[var(--accent-secondary)] ${openIndex === index ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M19 9l-7 7-7-7" strokeWidth={3} /></svg>
