};

const PricingOffer: React.FC<{ price: number, currency: string }> = ({ price, currency }) => {
    const offerPrice = parseFloat((price * (CURRENCY_RATES_FROM_USD[currency] || 1)).toFixed(2));
    const originalPrice = parseFloat((offerPrice * 1.25).toFixed(2));
    const savings = parseFloat((originalPrice - offerPrice).toFixed(2));
    const [timeLeft, setTimeLeft] = useState(1440);

    useEffect(() => {
        const timer = setInterval(() => setTimeLeft(p => Math.max(0, p - 1)), 1000);
        return () => clearInterval(timer);
    }, []);

    const mm = Math.floor(timeLeft / 60);
    const ss = timeLeft % 60;

    return (
        <div className="mt-12 p-10 rounded-[3.5rem] border shadow-4xl relative overflow-hidden group" style={{ backgroundColor: 'var(--bg-secondary)', borderColor: 'var(--border-color)' }}>
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[var(--accent-secondary)] to-transparent animate-pulse"></div>
            <div className="flex justify-between items-center relative z-10">
                <div>
                    <span className="text-[11px] font-black uppercase tracking-[0.5em] text-zinc-500 mb-3 block">Protocol Matrix Rate</span>
                    <span className="text-lg line-through text-zinc-600 font-mono block opacity-60 mb-1">
                        {currency} {originalPrice.toLocaleString()}
                    </span>
                    <div className="text-5xl md:text-7xl font-black text-white font-mono leading-none tracking-tighter">
                        {currency} {offerPrice.toLocaleString()}
                    </div>
                </div>
                <div className="text-right hidden sm:block">
                    <div className="px-6 py-2.5 bg-green-500/10 border border-green-500/30 text-green-400 rounded-full text-[10px] font-black uppercase tracking-luxury shadow-[0_0_20px_rgba(34,197,94,0.15)]">
                        Yield: {currency} {savings.toLocaleString()}
                    </div>
                </div>
            </div>
            <div className="mt-10 flex items-center justify-center gap-4 py-3.5 bg-black/50 rounded-2xl border border-white/5">
                <span className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">Neural Lock Expiry:</span>
                <span className="font-mono font-black text-2xl text-[var(--accent-primary)] tabular-nums tracking-[0.2em] drop-shadow-[0_0_15px_#00f2fe]">
                  {String(mm).padStart(2, '0')}:{String(ss).padStart(2, '0')}
                </span>
            </div>
        </div>
    );
};

const TourDetailPage: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();
  const { currency, addBooking, theme } = useAppContext();
  const navigate = useNavigate();
  const [pax, setPax] = useState(1);
  const [weather, setWeather] = useState('');
  const [isWeatherLoading, setIsWeatherLoading] = useState(false);
  const [funFacts, setFunFacts] = useState('');
  const [isFunFactsLoading, setIsFunFactsLoading] = useState(false);
  const [packingList, setPackingList] = useState('');
  const [isPackingListLoading, setIsPackingListLoading] = useState(false);

  const [isGeneratingVideo, setIsGeneratingVideo] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [videoStatus, setVideoStatus] = useState('');
  const [isVROpen, setIsVROpen] = useState(false);

  const tour = TOURS_DATA.find(t => t.slug === slug);
  const [selectedImage, setSelectedImage] = useState(tour?.images[0]);

  useEffect(() => { window.scrollTo(0, 0); if(tour) setSelectedImage(tour.images[0]); }, [slug, tour]);

  const tourMarker = useMemo(() => tour ? [{ lat: tour.latitude, lng: tour.longitude, popupContent: `<h3 style="font-weight:900; font-family:Cinzel; font-size:16px; margin:0; text-transform:uppercase;">${tour.title}</h3>` }] : [], [tour]);

  const handleAIQuery = async (type: 'weather' | 'facts' | 'packing') => {
    if (!tour) return;
    const setters: Record<'weather' | 'facts' | 'packing', [React.Dispatch<React.SetStateAction<boolean>>, React.Dispatch<React.SetStateAction<string>>]> = { 
      weather: [setIsWeatherLoading, setWeather], 
      facts: [setIsFunFactsLoading, setFunFacts], 
      packing: [setIsPackingListLoading, setPackingList] 
    };
    const [setLoading, setContent] = setters[type];
    setLoading(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const prompts = {
          weather: `5-day professional atmospheric forecast for ${tour.city}. Markdown table.`,
          facts: `3 rare, architecturally significant node facts about ${tour.city}. Markdown bullets.`,
          packing: `Elite tactical hardware requirements for ${tour.city}. Markdown.`
        };
        const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompts[type] });
        setContent(response.text || '');
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const generateMissionBriefing = async () => {
    if (!tour) return;
    try {
        const hasKey = await window.aistudio?.hasSelectedApiKey();
        if (hasKey === false) await window.aistudio?.openSelectKey();
    } catch (e) { console.warn("aistudio unavailable"); }

    setIsGeneratingVideo(true);
    setVideoStatus('Initializing Neural Pipeline...');

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const prompt = `Hyper-realistic 4k cinematic flyover of ${tour.city} showcasing ${tour.title}. High-fidelity lighting, epic scale, luxury travel atmosphere.`;

        setVideoStatus('Synthesizing Frame Nodes...');
        let operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt,
            config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
        });

        while (!operation.done) {
            setVideoStatus(`Rendering Neural Core: ${Math.floor(Math.random() * 25 + 15)}%...`);
            await new Promise(resolve => setTimeout(resolve, 8000));
            operation = await ai.operations.getVideosOperation({ operation });
        }

        setVideoStatus('Finalizing Global Link...');
        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (downloadLink) {
            const resp = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
            const blob = await resp.blob();
            setVideoUrl(URL.createObjectURL(blob));
        }
    } catch (err: any) {
        if (err.message?.includes("Requested entity was not found")) {
            setVideoStatus("Link Failure. Refresh API Key.");
            window.aistudio?.openSelectKey();
        } else {
            setVideoStatus("Synthesis Terminated.");
        }
        console.error(err);
    } finally {
        setIsGeneratingVideo(false);
    }
  };

