                </div>
                <div className="text-right hidden sm:block">
                    <div className="px-6 py-2.5 bg-green-500/10 border border-green-500/30 text-green-400 rounded-full text-[10px] font-black uppercase tracking-luxury shadow-[0_0_20px_rgba(34,197,94,0.2)]">
