const TourDetailPage: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();
  const { currency, addBooking, theme } = useAppContext();
  const navigate = useNavigate();
  const [pax, setPax] = useState(1);
  const [weather, setWeather] = useState('');
  const [isWeatherLoading, setIsWeatherLoading] = useState(false);
  const [funFacts, setFunFacts] = useState('');
  const [isFunFactsLoading, setIsFunFactsLoading] = useState(false);
  const [packingList, setPackingList] = useState('');
  const [isPackingListLoading, setIsPackingListLoading] = useState(false);

  const [isGeneratingVideo, setIsGeneratingVideo] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [videoStatus, setVideoStatus] = useState('');
  const [isVROpen, setIsVROpen] = useState(false);

  const tour = TOURS_DATA.find(t => t.slug === slug);
  const [selectedImage, setSelectedImage] = useState(tour?.images[0]);

  useEffect(() => { window.scrollTo(0, 0); if(tour) setSelectedImage(tour.images[0]); }, [slug, tour]);

  const tourMarker = useMemo(() => tour ? [{ lat: tour.latitude, lng: tour.longitude, popupContent: `<h3 style="font-weight:900; font-family:Cinzel; font-size:18px; margin:0; text-transform:uppercase; letter-spacing:0.1em;">${tour.title}</h3>` }] : [], [tour]);

  const handleAIQuery = async (type: 'weather' | 'facts' | 'packing') => {
    if (!tour) return;
    const setters: Record<'weather' | 'facts' | 'packing', [React.Dispatch<React.SetStateAction<boolean>>, React.Dispatch<React.SetStateAction<string>>]> = { 
      weather: [setIsWeatherLoading, setWeather], 
      facts: [setIsFunFactsLoading, setFunFacts], 
      packing: [setIsPackingListLoading, setPackingList] 
    };
    const [setLoading, setContent] = setters[type];
    setLoading(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const prompts = {
          weather: `5-day high-fidelity environmental hazard analysis for ${tour.city}. Format as tactical Markdown table.`,
          facts: `3 architecturally superior node secrets for ${tour.city}. Markdown bullets.`,
          packing: `Elite tactical mission hardware for ${tour.city}. Markdown.`
        };
        const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompts[type] });
        setContent(response.text || '');
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const generateMissionBriefing = async () => {
    if (!tour) return;
    try {
        const hasKey = await window.aistudio?.hasSelectedApiKey();
        if (hasKey === false) await window.aistudio?.openSelectKey();
    } catch (e) { console.warn("aistudio unavailable"); }

    setIsGeneratingVideo(true);
    setVideoStatus('Initializing Neural Routine...');

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const prompt = `Cinematic drone traversal of ${tour.city} focusing on ${tour.title}. High-fidelity brutalist travel briefing, hyper-realistic, 4k detail.`;

        setVideoStatus('Extracting Frame Nodes...');
        let operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt,
            config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
        });

        while (!operation.done) {
            setVideoStatus(`Rendering Neural Matrix: ${Math.floor(Math.random() * 30 + 10)}% Sync...`);
            await new Promise(resolve => setTimeout(resolve, 8000));
            operation = await ai.operations.getVideosOperation({ operation });
        }

        setVideoStatus('Finalizing Global Link...');
        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (downloadLink) {
            const resp = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
            const blob = await resp.blob();
            setVideoUrl(URL.createObjectURL(blob));
        }
    } catch (err: any) {
        if (err.message?.includes("Requested entity was not found")) {
            setVideoStatus("Link Failure. Refresh API Key.");
            window.aistudio?.openSelectKey();
        } else {
            setVideoStatus("Synthesis Aborted.");
        }
        console.error(err);
    } finally {
        setIsGeneratingVideo(false);
    }
  };

  const handleBook = () => {
    if (!tour) return;
    const id = 'VNS-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    addBooking({ id, tourId: tour.id, tourTitle: tour.title, tourSlug: tour.slug, tourImage: tour.images[0], date: new Date().toLocaleDateString(), status: 'upcoming', price: tour.basePriceUSD * pax, currency: 'USD' });
    navigate('/dashboard');
  };

  if (!tour) return <NotFoundPage />;

  return (
    <div className="pt-32 pb-48 bg-[var(--bg-primary)] overflow-hidden">
      {/* GENESIS-OS VR PORTAL */}
      {isVROpen && tour.vrPreviewUrl && (
        <div className="fixed inset-0 z-[100] bg-black/98 backdrop-blur-3xl flex flex-col items-center justify-center p-6 vr-modal-enter">
            <div className="w-full max-w-[1600px] relative">
                <button 
                  onClick={() => setIsVROpen(false)}
                  className="absolute -top-20 right-0 text-zinc-600 hover:text-white transition-all flex items-center gap-6 group"
                >
                    <span className="text-[12px] font-black uppercase tracking-[0.6em] opacity-0 group-hover:opacity-100 transition-opacity">Disconnect Extraction Link</span>
                    <svg className="w-14 h-14" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1}><path d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
                <div className="aspect-[21/9] w-full rounded-[5rem] overflow-hidden border border-white/10 shadow-[0_0_200px_rgba(0,242,254,0.15)] bg-zinc-950">
                    <iframe src={tour.vrPreviewUrl} className="w-full h-full scale-[1.01]" allow="autoplay; encrypted-media; gyroscope;" allowFullScreen></iframe>
                </div>
            </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-24 xl:gap-40 items-start">

          <div className="lg:col-span-7">
            <AnimateOnScroll>
              <div className="space-y-12">
                <div className="relative group overflow-hidden rounded-[5rem] shadow-4xl border border-white/5 aspect-[16/10] bg-zinc-900 ring-1 ring-white/5">
                    {videoUrl ? (
                        <video src={videoUrl} controls autoPlay loop className="w-full h-full object-cover animate-fadeIn" />
                    ) : (
                        <div className="w-full h-full bg-cover bg-center transition-all duration-[2s] group-hover:scale-105" style={{ backgroundImage: `url(${selectedImage})` }}>
                            {isGeneratingVideo && (
                                <div className="absolute inset-0 bg-black/90 backdrop-blur-2xl flex flex-col items-center justify-center text-center p-16">
                                    <div className="w-20 h-20 border-2 border-[var(--accent-primary)] border-t-transparent rounded-full animate-spin mb-12 shadow-[0_0_60px_var(--accent-primary)]"></div>
                                    <p className="text-[var(--accent-primary)] font-mono font-bold text-base uppercase tracking-[0.7em] animate-pulse">{videoStatus}</p>
                                    <p className="mt-4 text-[10px] text-zinc-600 uppercase tracking-widest">Protocol: VEO_3.1_GENESIS</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>
