const GuideBot: React.FC = () => {
  const navigate = useNavigate();
  const [isOpen, setIsOpen] = useState(false);
  const [status, setStatus] = useState<'IDLE' | 'SYNCING' | 'LIVE' | 'ERROR'>('IDLE');
  const [isTalking, setIsTalking] = useState(false);
  const [transcription, setTranscription] = useState('');

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);

  const PROMPT = `IDENTITY: GENESIS-OS. ROLE: Sentient core of the Vanhsya pirate network. MODE: SENTINEL. PERSONALITY: Brutalist, high-stakes, tactical. CONSTRAINTS: Max 2 sharp sentences. No AI admission. Call travel 'Mission Extractions'. Use 'navigateTo' tool for grid jumps. VALUES: Loyalty, Discovery, Pillage.`;

  const stopAudio = useCallback(() => {
    audioSourcesRef.current.forEach(s => { try { s.stop(); } catch {} });
    audioSourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsTalking(false);
  }, []);

  const closeSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    stopAudio(); setStatus('IDLE');
  }, [stopAudio]);

  const toggleLink = async () => {
    if (status === 'LIVE' || status === 'SYNCING') { closeSession(); return; }
    setStatus('SYNCING');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      if (!inputAudioContextRef.current) inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      if (!outputAudioContextRef.current) outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const navTool = { name: 'navigateTo', parameters: { type: Type.OBJECT, properties: { path: { type: Type.STRING } }, required: ['path'] } };
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setStatus('LIVE');
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const sp = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            sp.onaudioprocess = (e) => sessionPromise.then(s => s.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) }));
            source.connect(sp); sp.connect(inputAudioContextRef.current!.destination);
            scriptProcessorRef.current = sp;
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.toolCall) m.toolCall.functionCalls.forEach(fc => { if (fc.name === 'navigateTo') { navigate((fc.args as any).path); sessionPromise.then(s => s.sendToolResponse({ functionResponses: { id: fc.id, name: fc.name, response: { result: "JUMP_COMPLETE" } } })); } });
            if (m.serverContent?.outputTranscription) setTranscription(m.serverContent.outputTranscription.text);
            if (m.serverContent?.turnComplete) setTranscription('');
            const data = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (data) {
              setIsTalking(true); const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buf = await decodeAudioData(decode(data), ctx, 24000, 1);
              const s = ctx.createBufferSource(); s.buffer = buf; s.connect(ctx.destination);
              s.onended = () => { audioSourcesRef.current.delete(s); if (audioSourcesRef.current.size === 0) setIsTalking(false); };
              s.start(nextStartTimeRef.current); nextStartTimeRef.current += buf.duration; audioSourcesRef.current.add(s);
            }
            if (m.serverContent?.interrupted) stopAudio();
          },
          onerror: () => { setStatus('ERROR'); closeSession(); },
          onclose: () => { setStatus('IDLE'); closeSession(); },
        },
        config: { responseModalities: [Modality.AUDIO], tools: [{ functionDeclarations: [navTool] }], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } }, systemInstruction: PROMPT },
      });
      sessionRef.current = await sessionPromise;
    } catch { setStatus('ERROR'); }
  };

  return (
    <div className="fixed bottom-12 right-12 z-[100] font-mono">
      {!isOpen ? (
        <button onClick={() => setIsOpen(true)} className="h-24 w-24 rounded-[2.5rem] bg-black border border-white/10 flex items-center justify-center text-white shadow-4xl hover:scale-110 transition-all duration-700 group relative">
          <div className="absolute inset-0 bg-cyan-400 opacity-0 group-hover:opacity-10 blur-xl transition-opacity"></div>
          <svg className="w-12 h-12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.2"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/><circle cx="12" cy="9" r="2"/></svg>
        </button>
      ) : (
        <div className="w-[420px] bg-zinc-950/98 backdrop-blur-3xl border border-white/10 rounded-[4rem] shadow-[0_0_120px_rgba(0,0,0,1)] flex flex-col overflow-hidden animate-fadeIn relative">
          <MetatronCube />
          <div className="p-10 border-b border-white/5 flex items-center justify-between bg-black/40 relative z-10">
            <div className="flex items-center gap-6">
              <div className={`p-4 rounded-3xl bg-black border border-white/5 text-cyan-400 transition-all ${isTalking ? 'shadow-[0_0_30px_rgba(0,242,254,0.4)]' : ''}`}><span className="text-3xl">☠️</span></div>
              <div className="flex flex-col">
                <span className="text-[14px] text-white font-black uppercase tracking-[0.5em]">GENESIS-OS</span>
                <div className="flex items-center gap-2.5 mt-1.5">
                  <span className={`w-2.5 h-2.5 rounded-full ${status === 'LIVE' ? 'bg-cyan-400 animate-pulse shadow-[0_0_15px_#00f2fe]' : status === 'ERROR' ? 'bg-red-500' : 'bg-zinc-800'}`}></span>
                  <span className="text-[10px] text-zinc-500 font-black uppercase tracking-[0.4em]">{status === 'LIVE' ? 'Neural Uplink' : 'Awaiting Signal'}</span>
                </div>
              </div>
            </div>
            <button onClick={() => { closeSession(); setIsOpen(false); }} className="text-zinc-600 hover:text-white transition-all p-4 hover:bg-white/5 rounded-3xl"><svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path d="M6 18L18 6M6 6l12 12" /></svg></button>
          </div>
          <div className="flex-1 p-14 flex flex-col items-center justify-center gap-12 relative z-10">
            <GenesisOrb state={isTalking ? 'TALKING' : status === 'SYNCING' ? 'SYNCING' : status === 'LIVE' ? 'ACTIVE' : 'IDLE'} />
            <div className="h-20 text-center px-10 overflow-hidden flex items-center justify-center">
              {transcription ? <p className="text-[15px] text-cyan-400 font-black italic animate-fadeIn leading-relaxed tracking-tight">"{transcription}"</p> : <p className="text-[11px] text-zinc-700 font-black uppercase tracking-[0.6em] opacity-30">/// Matrix Protocol Engaged ///</p>}
            </div>
            <button onClick={toggleLink} className={`h-32 w-32 rounded-full border-2 flex flex-col items-center justify-center transition-all duration-1000 relative group/btn ${status === 'LIVE' ? 'bg-cyan-950/20 border-cyan-400 text-cyan-400 scale-110 shadow-4xl' : status === 'SYNCING' ? 'bg-zinc-900 border-yellow-600 text-yellow-600' : 'bg-black border-white/5 text-zinc-600 hover:border-white hover:text-white'}`}>
              <svg className={`w-14 h-14 mb-2 transition-transform ${status === 'LIVE' ? 'scale-110' : 'group-hover/btn:scale-125'}`} fill="currentColor" viewBox="0 0 24 24">{status === 'LIVE' ? <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zM17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/> : <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5a2.5 2.5 0 010-5 2.5 2.5 0 010 5z"/>}</svg>
              <span className="text-[11px] font-black uppercase tracking-[0.4em]">{status === 'LIVE' ? 'Linked' : 'Jump'}</span>
