              <div className="h-1 w-full bg-white/5 rounded-full overflow-hidden border border-white/5"><div className={`h-full bg-cyan-400 transition-all duration-[2s] ${isTalking ? 'w-full shadow-[0_0_30px_#00f2fe]' : 'w-0'}`}></div></div>
