const Loader: React.FC = () => {
    const [progress, setProgress] = useState(0);
    useEffect(() => {
        const timer = setInterval(() => setProgress(p => p < 99 ? p + Math.random() * 2 : 99), 100);
        return () => clearInterval(timer);
    }, []);
