const AIPlannerPage: React.FC = () => {
    const [step, setStep] = useState(1);
    const [destination, setDestination] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [itinerary, setItinerary] = useState('');
    const [imageUrl, setImageUrl] = useState<string | null>(null);

    const handleSubmit = async () => {
        setIsLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            const prompt = `Create a high-octane 3-day extraction mission itinerary for ${destination}. Format as cinematic Markdown. Use tactical terms like 'Drop', 'Extraction', 'Node'.`;
            const resp = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
            setItinerary(resp.text || '');

            const imgResp = await ai.models.generateContent({
              model: 'gemini-2.5-flash-image',
              contents: { parts: [{ text: `Cinematic brutalist travel photography of ${destination}, neon highlights, award-winning composition.` }] },
              config: { imageConfig: { aspectRatio: "16:9" } }
            });
            for (const part of imgResp.candidates[0].content.parts) {
              if (part.inlineData) setImageUrl(`data:image/png;base64,${part.inlineData.data}`);
            }
        } catch (err) { console.error(err); } finally { setIsLoading(false); }
    };

    if (isLoading) return <div className="pt-48 pb-32"><Loader /></div>;

    if (itinerary) return (
      <div className="max-w-screen-xl mx-auto px-10 pt-56 pb-64 animate-fadeIn">
        <AnimateOnScroll className="text-center mb-40">
           <h1 className="text-[var(--h-node)] font-black font-cinzel text-white leading-none uppercase mb-12">Mission <span className="adrenaline-gradient">Blueprint</span></h1>
           <p className="text-3xl text-zinc-500 italic font-light">"{destination.toUpperCase()} Extraction Logs"</p>
        </AnimateOnScroll>

        {imageUrl && (
          <div className="rounded-[6rem] overflow-hidden shadow-5xl mb-32 border border-white/10 aspect-[21/9] ring-2 ring-white/5">
            <img src={imageUrl} className="w-full h-full object-cover" />
          </div>
        )}

        <div className="p-20 glass-morgen rounded-[5rem] border-white/5 shadow-5xl">
            <div className={`prose prose-2xl prose-invert max-w-none font-light italic text-zinc-400`} dangerouslySetInnerHTML={{ __html: window.marked.parse(itinerary) }} />
            <div className="mt-20 pt-16 border-t border-white/10 flex justify-center">
              <button onClick={() => setItinerary('')} className="px-20 py-8 bg-white text-black font-black uppercase tracking-[0.5em] text-[12px] rounded-full hover:bg-[var(--accent-adrenaline)] transition-all transform hover:scale-110">Generate New Protocol</button>
            </div>
        </div>
      </div>
    );

    return (
        <div className="relative min-h-screen pt-48 pb-64 bg-transparent overflow-hidden">
            <div className="max-w-4xl mx-auto px-10 relative z-10 flex flex-col items-center">
                <AnimateOnScroll className="text-center mb-32">
                    <span className="text-tech text-cyan-400 mb-10 block">/// NEURAL_MISSION_ARCHITECT ///</span>
                    <h1 className="text-[var(--h-node)] font-black font-cinzel leading-none text-white tracking-tight-titles uppercase mb-14">The Architect</h1>
                    <p className="text-3xl text-zinc-600 font-light italic leading-relaxed tracking-tight">Design your planetary extraction blueprint with total precision.</p>
                </AnimateOnScroll>

                <div className="w-full glass-morgen rounded-[4rem] p-16 md:p-24 shadow-5xl border-white/10 relative overflow-hidden group hover:border-[var(--accent-adrenaline)]/30 transition-all duration-1000">
                    {step === 1 ? (
                      <div className="animate-fadeIn">
                        <label className="text-tech text-zinc-600 mb-10 block">ESTABLISH_TARGET_NODE</label>
                        <input 
                          type="text" 
                          placeholder="e.g. TOKYO_CITADEL" 
                          value={destination}
                          onChange={e => setDestination(e.target.value)}
                          className="w-full bg-transparent border-b-4 border-white/10 text-6xl md:text-8xl font-black font-cinzel text-white outline-none focus:border-[var(--accent-adrenaline)] transition-all uppercase placeholder:opacity-10 py-10 mb-20"
                        />
                        <button 
                          disabled={!destination}
                          onClick={() => setStep(2)}
                          className="w-full py-10 bg-white text-black font-black uppercase tracking-[0.8em] text-[14px] rounded-full hover:bg-[var(--accent-adrenaline)] transition-all transform hover:scale-105 disabled:opacity-30"
                        >
                          Establish Link
                        </button>
                      </div>
                    ) : (
                      <div className="animate-fadeIn">
                        <label className="text-tech text-zinc-600 mb-14 block">SELECT_MISSION_PARAMETERS</label>
                        <div className="grid grid-cols-2 gap-12 mb-20">
                          {interestOptions.map(opt => (
                            <button key={opt.name} className="p-16 rounded-[3rem] border border-white/5 hover:border-[var(--accent-adrenaline)]/40 hover:bg-white/5 transition-all flex flex-col items-center text-center group">
                                <div className="text-white group-hover:text-[var(--accent-adrenaline)] transition-colors">{opt.icon}</div>
                                <span className="text-tech text-white group-hover:text-[var(--accent-adrenaline)]">{opt.name}</span>
                            </button>
                          ))}
                        </div>
                        <div className="flex gap-8">
                          <button onClick={() => setStep(1)} className="px-14 py-8 glass-morgen text-zinc-500 font-black uppercase tracking-[0.4em] rounded-full hover:text-white transition-all">Back</button>
                          <button onClick={handleSubmit} className="flex-1 py-10 bg-[var(--accent-adrenaline)] text-black font-black uppercase tracking-[0.6em] text-[14px] rounded-full hover:bg-white transition-all transform hover:scale-105 shadow-5xl">Execute Protocol</button>
                        </div>
                      </div>
                    )}
                </div>
            </div>

            {/* Background Ambience */}
            <div className="absolute top-0 right-0 w-[800px] h-[800px] bg-purple-600/5 rounded-full blur-[150px] pointer-events-none -translate-y-1/2 translate-x-1/2"></div>
            <div className="absolute bottom-0 left-0 w-[600px] h-[600px] bg-cyan-400/5 rounded-full blur-[150px] pointer-events-none translate-y-1/2 -translate-x-1/2"></div>
        </div>
    );
};

