const PricingOffer: React.FC<{ price: number, currency: string }> = ({ price, currency }) => {
    const offerPrice = parseFloat((price * (CURRENCY_RATES_FROM_USD[currency] || 1)).toFixed(2));
    const originalPrice = parseFloat((offerPrice * 1.35).toFixed(2));
    const [timeLeft, setTimeLeft] = useState(1440);

    useEffect(() => {
        const timer = setInterval(() => setTimeLeft(p => Math.max(0, p - 1)), 1000);
        return () => clearInterval(timer);
    }, []);

    const mm = Math.floor(timeLeft / 60);
    const ss = timeLeft % 60;

    return (
        <div className="mt-16 p-14 rounded-[4rem] border shadow-5xl relative overflow-hidden glass-morgen border-white/10 group">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[var(--accent-adrenaline)] to-transparent animate-pulse shadow-[0_0_20px_var(--accent-adrenaline)]"></div>
            <div className="flex justify-between items-end relative z-10 mb-12">
                <div>
                    <span className="text-tech text-zinc-500 mb-6 block">/// MISSION_EXTRACTION_FEE ///</span>
                    <span className="text-2xl line-through text-zinc-700 font-mono block mb-2">
                        {currency} {originalPrice.toLocaleString()}
                    </span>
                    <div className="text-7xl md:text-9xl font-black text-white font-mono leading-none tracking-tighter adrenaline-gradient">
                        {currency} {offerPrice.toLocaleString()}
                    </div>
                </div>
                <div className="text-right">
                    <div className="px-8 py-3 bg-[var(--accent-adrenaline)]/10 border border-[var(--accent-adrenaline)]/30 text-[var(--accent-adrenaline)] rounded-full text-[11px] font-black uppercase tracking-luxury animate-pulse">
                        EXTRACT_YIELD: 35%
                    </div>
                </div>
            </div>
            <div className="mt-12 flex items-center justify-center gap-10 py-6 bg-black/40 rounded-[2rem] border border-white/5 ring-1 ring-white/10">
                <span className="text-tech text-zinc-600">PROTOCOL_TIMEOUT:</span>
                <span className="font-mono font-black text-4xl text-white tabular-nums tracking-[0.2em] shadow-glow">
                  {String(mm).padStart(2, '0')}:{String(ss).padStart(2, '0')}
                </span>
            </div>
        </div>
    );
};

const TourDetailPage: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();
  const { currency, addBooking, theme } = useAppContext();
  const navigate = useNavigate();
  const [pax, setPax] = useState(1);
  const [isVROpen, setIsVROpen] = useState(false);
  const [isGeneratingVideo, setIsGeneratingVideo] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [videoStatus, setVideoStatus] = useState('');

  const tour = TOURS_DATA.find(t => t.slug === slug);
  const [selectedImage, setSelectedImage] = useState(tour?.images[0]);

  useEffect(() => { window.scrollTo(0, 0); if(tour) setSelectedImage(tour.images[0]); }, [slug, tour]);

  const tourMarker = useMemo(() => tour ? [{ lat: tour.latitude, lng: tour.longitude, popupContent: `<h3 style="font-weight:900; font-family:Cinzel; font-size:18px; margin:0; text-transform:uppercase; letter-spacing:0.1em;">${tour.title}</h3>` }] : [], [tour]);

  const generateMissionBriefing = async () => {
    if (!tour) return;
    setIsGeneratingVideo(true);
    setVideoStatus('SYNCHRONIZING_GRID...');

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const prompt = `Highly cinematic 4K drone sweep of ${tour.city} focusing on ${tour.title}. Brutalist architecture, neon highlights, luxury atmosphere.`;

        let operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt,
            config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
        });

        while (!operation.done) {
            setVideoStatus(`EXTRACTION_SYNC: ${Math.floor(Math.random() * 40 + 20)}%...`);
            await new Promise(resolve => setTimeout(resolve, 8000));
            operation = await ai.operations.getVideosOperation({ operation });
        }

        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (downloadLink) {
            const resp = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
            const blob = await resp.blob();
            setVideoUrl(URL.createObjectURL(blob));
        }
    } catch (err: any) {
        setVideoStatus("LINK_FAILURE_DETECTED.");
        console.error(err);
    } finally {
        setIsGeneratingVideo(false);
    }
  };

  const handleBook = () => {
    if (!tour) return;
    const id = 'VNS-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    addBooking({ id, tourId: tour.id, tourTitle: tour.title, tourSlug: tour.slug, tourImage: tour.images[0], date: new Date().toLocaleDateString(), status: 'upcoming', price: tour.basePriceUSD * pax, currency: 'USD' });
    navigate('/dashboard');
  };

  if (!tour) return <NotFoundPage />;

  return (
    <div className="pt-48 pb-64 bg-[var(--bg-primary)] overflow-hidden relative">

      {/* SPATIAL EXTRACTION PORTAL (VR) */}
      {isVROpen && (
        <div className="fixed inset-0 z-[100] bg-black/98 backdrop-blur-[100px] flex flex-col items-center justify-center p-8 animate-fadeIn">
            <div className="w-full max-w-screen-2xl relative">
                <button onClick={() => setIsVROpen(false)} className="absolute -top-24 right-0 text-zinc-500 hover:text-white transition-all flex items-center gap-8 group">
                    <span className="text-tech opacity-0 group-hover:opacity-100 transition-all">DISCONNECT_LINK</span>
                    <div className="p-4 rounded-full border border-white/10 group-hover:bg-red-500 group-hover:text-black transition-all">
                      <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1}><path d="M6 18L18 6M6 6l12 12" /></svg>
                    </div>
                </button>
                <div className="aspect-[21/9] w-full rounded-[6rem] overflow-hidden border border-white/10 shadow-[0_0_200px_rgba(0,242,254,0.3)] bg-black ring-2 ring-white/5">
                    <iframe src={tour.vrPreviewUrl} className="w-full h-full scale-[1.01]" allow="autoplay; encrypted-media; gyroscope;" allowFullScreen></iframe>
                </div>
            </div>
        </div>
      )}

      <div className="max-w-screen-2xl mx-auto px-10">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-32 items-start">

          {/* VISUAL CORE */}
          <div className="lg:col-span-7">
            <AnimateOnScroll>
              <div className="space-y-16">
                <div className="relative group overflow-hidden rounded-[6rem] shadow-5xl border border-white/5 aspect-[16/10] bg-black ring-1 ring-white/5">
                    {videoUrl ? (
                        <video src={videoUrl} controls autoPlay loop className="w-full h-full object-cover animate-fadeIn" />
                    ) : (
                        <div className="relative w-full h-full">
                            {/* Hotspots */}
                            {tour.hotspots && tour.hotspots.map((hotspot, idx) => (
                                <HotspotUI key={idx} hotspot={hotspot} />
                            ))}

                            <div 
                                className="w-full h-full bg-cover bg-center transition-all duration-[3s] group-hover:scale-110" 
                                style={{ backgroundImage: `url(${selectedImage})` }}
                            >
                                {isGeneratingVideo && (
                                    <div className="absolute inset-0 bg-black/95 backdrop-blur-[80px] flex flex-col items-center justify-center text-center p-20 z-30">
                                        <div className="w-24 h-24 border-2 border-[var(--accent-adrenaline)] border-t-transparent rounded-full animate-spin mb-16 shadow-glow"></div>
                                        <p className="text-[var(--accent-adrenaline)] font-mono font-black text-xl uppercase tracking-[0.8em] animate-pulse">{videoStatus}</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>
                <div className="grid grid-cols-4 gap-10">
                  {tour.images.map((img, i) => (
                    <button key={i} onClick={() => { setSelectedImage(img); setVideoUrl(null); }} className={`rounded-[3rem] overflow-hidden border-2 transition-all duration-1000 ${selectedImage === img && !videoUrl ? 'border-[var(--accent-adrenaline)] scale-110 shadow-5xl' : 'border-transparent opacity-30 hover:opacity-100 hover:scale-105'}`}>
                        <img src={img} alt="Frame" className="w-full h-32 md:h-44 object-cover" />
                    </button>
                  ))}
                </div>
              </div>
            </AnimateOnScroll>
          </div>

          {/* PARAMETER CORE */}
          <div className="lg:col-span-5 pt-12">
            <AnimateOnScroll delay="200ms">
              <span className="text-tech text-[var(--accent-adrenaline)] mb-12 block">/// MISSION_ARCH_ID: {tour.id} ///</span>
              <h1 className="text-[var(--h-node)] font-black font-cinzel leading-[0.82] text-white tracking-tight-titles mb-16 uppercase lux-text-gradient">{tour.title}</h1>

