                      <label className="text-tech text-zinc-600 mr-10">CREW:</label>
                      <input type="number" min="1" value={pax} onChange={(e) => setPax(Math.max(1, parseInt(e.target.value) || 1))} className="bg-transparent text-4xl font-mono font-black text-white w-20 outline-none" />
                  </div>
                  <button onClick={handleBook} className="flex-1 px-14 py-8 bg-white text-black font-black uppercase tracking-[0.6em] rounded-[2.5rem] transition-all transform hover:scale-105 active:scale-95 text-[14px] shadow-5xl hover:bg-[var(--accent-adrenaline)]">Commit Passport</button>
              </div>

              <div className="mt-10 grid grid-cols-2 gap-8">
                  <button onClick={generateMissionBriefing} disabled={isGeneratingVideo} className="px-10 py-8 glass-morgen border-white/10 text-cyan-400 font-black uppercase tracking-[0.5em] rounded-[2.5rem] hover:border-cyan-400 hover:bg-black transition-all text-[11px] disabled:opacity-30">
