                  </button>
                  {tour.vrPreviewUrl && (
                    <button onClick={() => setIsVROpen(true)} className="px-10 py-8 glass-morgen border-white/10 text-purple-500 font-black uppercase tracking-[0.5em] rounded-[2.5rem] hover:border-purple-500 hover:bg-black transition-all text-[11px]">
