const AIPlannerPage: React.FC = () => {
  const { currency } = useAppContext();
  const [step, setStep] = useState(1);
  const [destination, setDestination] = useState('');
  const [vibe, setVibe] = useState('Luxury');
  const [duration, setDuration] = useState(3);
  const [isLoading, setIsLoading] = useState(false);
  const [statusText, setStatusText] = useState('');
  const [dossier, setDossier] = useState<{ text: string; image: string | null }>({ text: '', image: null });

  // --- Core Engine: Mission Synthesis ---
  const synthesizeMission = async () => {
    setIsLoading(true);
    setStatusText('INITIATING_NEURAL_LINK...');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

      // Step 1: Generate Tactical Briefing (High Reasoning)
      setStatusText('CALIBRATING_EXTRACTION_SEQUENCE...');
      const textResponse = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Create an elite, high-octane 3-day travel itinerary for ${destination} focusing on a ${vibe} experience. 
        Format as professional Markdown. Use tactical terms: 'Extraction', 'Node', 'Drop Zone', 'Sync'. 
        Include a 'Mission Parameters' section at the top with: 
        - Risk Level: [Low/Med/High]
        - Signal Strength: [Optimal/Interference]
        - Estimated Yield: [High/Premium/Ultra]`,
        config: { thinkingConfig: { thinkingBudget: 4000 } }
      });

      // Step 2: Generate Visual Intel (Fast Creative)
      setStatusText('EXTRACTING_VISUAL_TELEMETRY...');
      const imageResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: `UHD Cinematic brutalist photography of ${destination}, neon highlights, ${vibe} atmosphere, luxury travel drone shot.` }] },
        config: { imageConfig: { aspectRatio: "16:9" } }
      });

      let base64Image = null;
      for (const part of imageResponse.candidates[0].content.parts) {
        if (part.inlineData) base64Image = `data:image/png;base64,${part.inlineData.data}`;
      }

      setDossier({ text: textResponse.text || '', image: base64Image });
      setStep(4);
    } catch (err) {
      console.error(err);
      setStatusText('LINK_FAILURE_DETECTED.');
    } finally {
      setIsLoading(false);
    }
  };

  // --- Screen: The Loading Sequence ---
  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-10 bg-[#030305]">
      <div className="relative w-64 h-64 mb-16">
        <div className="absolute inset-0 border-t-2 border-cyan-400 rounded-full animate-spin"></div>
        <div className="absolute inset-4 border-b-2 border-purple-500 rounded-full animate-spin-reverse"></div>
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="w-12 h-12 bg-white rounded-sm rotate-45 animate-pulse shadow-[0_0_30px_white]"></div>
        </div>
      </div>
      <p className="text-tech text-cyan-400 animate-pulse tracking-[1em] mb-4">{statusText}</p>
      <p className="text-zinc-600 font-mono text-xs uppercase italic">Syncing with global coordinate grid...</p>
    </div>
  );

  // --- Screen: The Final Dossier ---
  if (step === 4) return (
    <div className="pt-48 pb-64 px-10 max-w-7xl mx-auto animate-fadeIn">
      <AnimateOnScroll className="text-center mb-32">
        <span className="text-tech text-purple-400 mb-8 block">/// MISSION_DECRYPTION_COMPLETE ///</span>
        <h1 className="text-7xl md:text-9xl font-black font-cinzel text-white uppercase tracking-tight-titles leading-none">
          Extraction <span className="text-cyan-400">Log</span>
        </h1>
      </AnimateOnScroll>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-24">
        {/* Dossier Sidebar */}
        <div className="lg:col-span-4 space-y-12">
          {dossier.image && (
            <div className="rounded-[4rem] overflow-hidden border border-white/10 shadow-5xl aspect-square ring-2 ring-white/5">
              <img src={dossier.image} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-[3s]" alt="Target Node" />
            </div>
          )}
          <div className="p-12 glass-morgen rounded-[4rem] border-white/10 shadow-4xl space-y-10">
            <div>
              <p className="text-tech text-zinc-600 mb-2">TARGET_NODE</p>
              <p className="text-3xl font-black text-white font-cinzel">{destination.toUpperCase()}</p>
            </div>
            <div>
              <p className="text-tech text-zinc-600 mb-2">EXTRACTION_CURRENCY</p>
              <p className="text-3xl font-black text-white font-mono">{currency}</p>
            </div>
            <button 
              onClick={() => { setStep(1); setDestination(''); }}
              className="w-full py-6 bg-white/5 border border-white/10 text-white font-black uppercase tracking-[0.4em] text-[10px] rounded-full hover:bg-white hover:text-black transition-all"
            >
              Recalibrate Target
            </button>
          </div>
