      const textResponse = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Architect a high-octane ${duration}-day travel mission for ${destination} with a ${vibe} profile. 
        Format as ultra-modern Markdown. Use technical headers: 'DROP_ZONE', 'INTEL_NODE', 'EXTRACTION_WINDOW'. 
        Include a Mission Stats block with: Signal Fidelity [High], Local Corruption [Low], Extraction Yield [Premium].`,
        config: { thinkingConfig: { thinkingBudget: 4000 } }
      });

      // Step 2: Generate Cinematic Mission Briefing Video with Veo
      setStatusText('SYNTHESIZING_MISSION_BRIEFING_VIDEO...');
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
