        contents: `Architect a high-octane ${duration}-day travel mission for ${destination} with a ${vibe} profile. 
        Format as ultra-modern Markdown with the following headers: '## DROP_ZONE', '## MISSION_INTEL', '## EXTRACTION_TIMELINE'. 
        Include a 'MISSION_STATS' block with: 
        - Signal Fidelity: [Optimal]
        - Local Corruption: [Low]
        - Extraction Yield: [Ultra-High]
        - Gear Profile: [Tactical/Luxury]`,
        config: { thinkingConfig: { thinkingBudget: 4000 } }
      });

      // Step 2: Cinematic Mission Briefing Video
      setStatusText('SYNTHESIZING_BRIEFING_VIDEO...');
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: `Cinematic 4K drone sweep of ${destination} landscape, ${vibe} atmosphere, high contrast lighting, futuristic adventure mood, extreme wide shot.`,
        config: { numberOfVideos: 1, resolution: '1080p', aspectRatio: '16:9' }
      });

      while (!operation.done) {
        setStatusText(`ENCODING_VISUAL_INTEL: ${Math.floor(Math.random() * 20 + 40)}%...`);
        await new Promise(resolve => setTimeout(resolve, 8000));
        operation = await ai.operations.getVideosOperation({ operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      let missionVideo = null;
      if (downloadLink) {
        const resp = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await resp.blob();
        missionVideo = URL.createObjectURL(blob);
      }

      setDossier({ text: textResponse.text || '', video: missionVideo });
      setStep(4);
    } catch (err) {
      console.error(err);
      setStatusText('LINK_FAILURE_DETECTED.');
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-12 bg-[#030305] relative overflow-hidden">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(0,242,254,0.05)_0%,transparent_70%)] animate-pulse"></div>
      <div className="relative w-80 h-80 mb-20">
        <div className="absolute inset-0 border-t-2 border-cyan-400 rounded-full animate-spin shadow-glow"></div>
