  if (step === 4) return (
    <div className="pt-48 pb-64 px-10 max-w-7xl mx-auto animate-fadeIn">
      <AnimateOnScroll className="text-center mb-32">
        <span className="text-tech text-purple-500 mb-10 block animate-pulse">/// MISSION_DECRYPTION_COMPLETE ///</span>
