              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent pointer-events-none"></div>
              <div className="absolute bottom-10 left-10 text-tech text-[10px] text-cyan-400">VISUAL_CONFIRMATION: ACTIVE</div>
            </div>
          )}
          <div className="p-16 glass-morgen rounded-[5rem] border-white/5 shadow-5xl space-y-16 relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-2 h-full bg-cyan-400 shadow-glow"></div>
