          <div className="absolute top-0 right-0 p-20 opacity-[0.03] pointer-events-none">
            <svg className="w-96 h-96 text-white" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2L4 7v10l8 5 8-5V7l-8-5zm0 2.8L18 8v8l-6 3.7L6 16V8l6-3.2z"/></svg>
          </div>
          <div 
            className="prose prose-2xl prose-invert max-w-none font-light italic text-zinc-400 tracking-tight leading-relaxed prose-headings:font-cinzel prose-headings:text-white prose-headings:uppercase prose-headings:tracking-widest" 
            dangerouslySetInnerHTML={{ __html: window.marked.parse(dossier.text) }} 
