import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { useAppContext } from '../contexts/AppContext';
import AnimateOnScroll from '@/components/AnimateOnScroll';
import { Link } from 'react-router-dom';

declare global {
  interface Window {
    marked: any;
  }
}

const AIPlannerPage: React.FC = () => {
  const { currency } = useAppContext();
  const [step, setStep] = useState(1);
  const [destination, setDestination] = useState('');
  const [vibe, setVibe] = useState('Luxury');
  const [duration, setDuration] = useState(3);
  const [isLoading, setIsLoading] = useState(false);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<{ text: string; image: string | null }>({ text: '', image: null });

  const generatePlan = async () => {
    setIsLoading(true);
    setStatusText('Architecting your itinerary...');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

      // Step 1: Itinerary Generation
      const textResponse = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Create a professional and detailed ${duration}-day travel itinerary for ${destination} focusing on a ${vibe} experience. 
        Format as high-end Markdown. Include sections for 'Itinerary Overview', 'Daily Breakdown', and 'Pro Tips'. 
        Tone: Premium, expert, and inviting.`,
        config: { thinkingConfig: { thinkingBudget: 2000 } }
      });

      // Step 2: Destination Imagery
      setStatusText('Visualizing your destination...');
      const imageResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: `High-fidelity, cinematic photography of ${destination}, ${vibe} atmosphere, professional travel magazine style.` }] },
        config: { imageConfig: { aspectRatio: "16:9" } }
      });

      let base64Image = null;
      for (const part of imageResponse.candidates[0].content.parts) {
        if (part.inlineData) base64Image = `data:image/png;base64,${part.inlineData.data}`;
      }

      setResult({ text: textResponse.text || '', image: base64Image });
      setStep(4);
    } catch (err) {
      console.error(err);
      setStatusText('Failed to sync with AI nodes.');
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-12 bg-[#050505]">
      <div className="w-16 h-16 border-4 border-white/10 border-t-cyan-400 rounded-full animate-spin mb-8"></div>
      <p className="text-xl font-light text-zinc-400 animate-pulse font-cinzel uppercase tracking-[0.2em]">{statusText}</p>
    </div>
  );

  if (step === 4) return (
    <div className="pt-32 pb-48 px-6 max-w-5xl mx-auto animate-fadeIn">
      <h1 className="text-5xl md:text-7xl font-black font-cinzel text-white mb-12 uppercase text-center">Your <span className="lux-gradient">Bespoke</span> Plan</h1>

      <div className="space-y-12">
        {result.image && (
          <div className="rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 aspect-video">
            <img src={result.image} className="w-full h-full object-cover" alt="Destination visualization" />
          </div>
        )}

        <div className="p-12 glass-card rounded-[3rem] border-white/10 shadow-xl relative overflow-hidden">
          <div 
            className="prose prose-xl prose-invert max-w-none font-light italic text-zinc-400 leading-relaxed" 
            dangerouslySetInnerHTML={{ __html: window.marked.parse(result.text) }} 
          />
          <div className="mt-16 pt-12 border-t border-white/5 flex flex-col sm:flex-row justify-between items-center gap-8">
             <Link to="/treasure-hunt" className="px-12 py-5 bg-white text-black font-bold uppercase tracking-widest text-[12px] rounded-full hover:bg-cyan-400 transition-all">
               Confirm Details
             </Link>
             <button onClick={() => setStep(1)} className="text-zinc-500 hover:text-white font-bold uppercase tracking-widest text-[10px] transition-all">Start Over &rarr;</button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pt-32 pb-48 bg-[#050505] relative overflow-hidden">
      <div className="max-w-3xl mx-auto px-6 relative z-10 flex flex-col items-center">
        <AnimateOnScroll className="text-center mb-16">
          <span className="text-xs font-bold text-cyan-400 mb-6 block uppercase tracking-[0.4em]">Personalized Architecture</span>
          <h1 className="text-6xl md:text-8xl font-black font-cinzel text-white leading-tight uppercase mb-4">
            Itinerary <br/> <span className="lux-gradient italic font-light tracking-[-0.05em]">Planner</span>
          </h1>
          <p className="text-zinc-500 text-lg font-light italic">Step {step} of 3</p>
        </AnimateOnScroll>

        <div className="w-full glass-card rounded-[3rem] p-10 md:p-16 shadow-2xl border-white/10">
          {step === 1 && (
            <div className="animate-fadeIn">
              <label className="text-xs font-bold text-zinc-600 mb-4 block uppercase tracking-widest">Where would you like to go?</label>
              <input 
                type="text" 
                placeholder="City, Country, or Region" 
                value={destination}
                onChange={e => setDestination(e.target.value)}
                className="w-full bg-transparent border-b-2 border-white/10 text-4xl md:text-5xl font-black font-cinzel text-white outline-none focus:border-cyan-400 transition-all uppercase placeholder:opacity-5 py-6 mb-12"
              />
              <button 
                disabled={!destination}
                onClick={() => setStep(2)}
                className="w-full py-6 bg-white text-black font-bold uppercase tracking-widest text-[12px] rounded-full hover:bg-cyan-400 transition-all disabled:opacity-20"
              >
                Continue
              </button>
            </div>
          )}

          {step === 2 && (
            <div className="animate-fadeIn">
              <label className="text-xs font-bold text-zinc-600 mb-8 block uppercase tracking-widest text-center">What is the vibe of this journey?</label>
              <div className="grid grid-cols-2 gap-6 mb-12">
                {['Luxury', 'Gritty', 'Zen', 'Adrenaline'].map(v => (
                  <button 
                    key={v}
                    onClick={() => setVibe(v)}
                    className={`py-6 rounded-2xl border text-sm font-bold uppercase tracking-widest transition-all ${vibe === v ? 'bg-white text-black border-white' : 'bg-white/5 border-white/5 text-zinc-500 hover:border-white/20'}`}
                  >
                    {v}
                  </button>
                ))}
              </div>
              <div className="flex gap-4">
                <button onClick={() => setStep(1)} className="px-8 py-5 border border-white/10 text-zinc-500 font-bold uppercase tracking-widest text-[10px] rounded-full hover:text-white">Back</button>
                <button onClick={() => setStep(3)} className="flex-1 py-5 bg-white text-black font-bold uppercase tracking-widest text-[12px] rounded-full hover:bg-cyan-400">Continue</button>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="animate-fadeIn">
              <label className="text-xs font-bold text-zinc-600 mb-12 block uppercase tracking-widest text-center text-zinc-600">Duration in Days</label>
              <div className="mb-16">
                <input 
                  type="range" min="1" max="14" value={duration} 
                  onChange={e => setDuration(parseInt(e.target.value))}
                  className="w-full h-2 bg-white/10 rounded-full appearance-none cursor-pointer accent-cyan-400"
                />
                <div className="flex justify-between mt-6">
                   <p className="text-5xl font-black text-white font-mono">{duration}</p>
                   <p className="text-xs text-zinc-600 uppercase font-bold tracking-widest flex items-center">Days</p>
                </div>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setStep(2)} className="px-8 py-5 border border-white/10 text-zinc-500 font-bold uppercase tracking-widest text-[10px] rounded-full hover:text-white">Back</button>
                <button onClick={generatePlan} className="flex-1 py-6 bg-gradient-to-r from-cyan-400 to-purple-600 text-white font-black uppercase tracking-widest text-[12px] rounded-full shadow-xl hover:scale-105 transition-all">
                  Generate Plan
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AIPlannerPage;

