          </Link>

          <nav className="hidden lg:flex items-center space-x-4">
            {navLinks.map(link => (
              <NavLink 
                key={link.href}
                to={link.href} 
                className={({ isActive }) => `px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.4em] transition-all duration-500 fluid-text ${isActive ? 'text-cyan-400' : 'text-zinc-500 hover:text-white'}`}
              >
                {link.label}
              </NavLink>
            ))}
          </nav>

          <div className="flex items-center space-x-8">
            <button 
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} 
