        </div>

        {isMenuOpen && (
          <div className="lg:hidden mt-6 p-10 glass-card rounded-[3rem] animate-fadeIn shadow-5xl border-white/10">
            <nav className="flex flex-col space-y-8">
              {navLinks.map(link => (
                <NavLink key={link.href} to={link.href} onClick={() => setIsMenuOpen(false)} className="text-zinc-500 hover:text-white text-[10px] font-black uppercase tracking-[0.4em]">
                  {link.label}
